Object.assign(MOVIE_MENU_EDITIONS,{"Night of the Living Dead (1968)":{"poster":"assets/menu-posters/night-of-the-living-dead-1968.jpg","colour":"#343434","servings":4,"tagline":"They're coming to get you, Barbara.","cue":"Serve the snacks when everyone boards up the windows.","menu":{"s":[{"n":"Cemetery picnic sandwiches","note":"Egg and cress, ham and mustard on buttered white bread.","how":"Boil 2 eggs for 10 minutes, cool, peel and mash with 20g mayonnaise. Stir in 10g chopped cress. Butter 8 slices white bread with 25g softened butter. Use four slices to make two egg-and-cress sandwiches. Use the other four for two sandwiches with 80g leg ham and 10g Dijon mustard. Trim the crusts and cut each sandwich into four small pieces. Wrap in wax paper for a 1968-style picnic and serve four pieces each.","shop":["2 eggs@Dairy","20g mayonnaise@Pantry","10g cress@Produce","8 slices white bread@Bakery","25g butter@Dairy","80g leg ham@Deli","10g Dijon mustard@Pantry"]},{"n":"Black and white popcorn","note":"Buttered popcorn, half salted and half with pepper and black sesame.","how":"Pop 60g popcorn kernels in 1 tbsp neutral oil in a covered pot over medium heat for 3 to 4 minutes, shaking regularly. Divide equally. Toss one half with 15g melted butter and 1/4 tsp fine salt. Toss the other with 15g melted butter, 1/4 tsp cracked black pepper and 10g black sesame seeds. Arrange side by side in a shared bowl.","shop":["60g popcorn kernels@Pantry","1 tbsp neutral oil@Pantry","30g butter@Dairy","fine salt@Pantry","black pepper@Pantry","10g black sesame seeds@Pantry"]}],"m":[{"n":"Farmhouse stew","note":"Slow braised beef with onion, carrot, potato, thyme and crusty bread.","how":"Cut 800g beef chuck into chunks and season with 1/2 tsp salt and 1/4 tsp black pepper. Brown in 1 tbsp neutral oil in a heavy casserole for 8 minutes, in batches. Add 1 chopped brown onion, 2 chopped carrots, 500g potato chunks, 500ml beef stock and 4 thyme sprigs. Cover and braise at 160°C conventional for 2.5 hours, stirring once, until the beef is tender. Serve with 200g crusty Italian bread for soaking up the stock.","shop":["800g beef chuck@Meat","salt@Pantry","black pepper@Pantry","1 tbsp neutral oil@Pantry","1 brown onion@Produce","2 carrots@Produce","500g potatoes@Produce","500ml beef stock@Pantry","4 thyme sprigs@Produce","200g crusty Italian bread@Bakery"]}],"w":[{"n":"Black and white cookies","note":"Soft vanilla cookies iced half in vanilla and half in chocolate.","how":"Beat 60g softened butter with 60g caster sugar until pale. Beat in 1 egg and 1 tsp vanilla extract. Fold in 120g plain flour, 1/2 tsp baking powder and 40g sour cream. Spoon 8 rounds onto a lined tray and bake at 180°C conventional for 12 minutes until set. Cool completely. Mix 100g icing sugar with 2 to 3 tsp warm water to make vanilla fondant icing. Spread over half of each cookie. Mix 10g cocoa into the remaining icing, adding a little more water if needed, and ice the other halves. Let set and serve two each.","shop":["60g butter@Dairy","60g caster sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","120g plain flour@Pantry","1/2 tsp baking powder@Pantry","40g sour cream@Dairy","100g icing sugar@Pantry","10g cocoa@Pantry"]}],"d":[{"n":"Farmhouse lemonade","note":"Fresh lemon juice and sugar syrup with cold water and mint.","how":"Dissolve 80g caster sugar in 80ml hot water and cool. Mix the syrup with 120ml lemon juice and 700ml cold water in a large jug. Add 1 sliced lemon and 8 mint leaves. Refrigerate for 30 minutes and divide among four glasses.","shop":["80g caster sugar@Pantry","5 lemons for juice and slices@Produce","8 mint leaves@Produce"]}],"shopping":["3 eggs@Dairy","20g mayonnaise@Pantry","10g cress@Produce","8 slices white bread@Bakery","115g butter@Dairy","80g leg ham@Deli","10g Dijon mustard@Pantry","60g popcorn kernels@Pantry","2 tbsp neutral oil@Pantry","fine salt@Pantry","black pepper@Pantry","10g black sesame seeds@Pantry","800g beef chuck@Meat","1 brown onion@Produce","2 carrots@Produce","500g potatoes@Produce","500ml beef stock@Pantry","4 thyme sprigs@Produce","200g crusty Italian bread@Bakery","140g caster sugar@Pantry","1 tsp vanilla extract@Pantry","120g plain flour@Pantry","1/2 tsp baking powder@Pantry","40g sour cream@Dairy","100g icing sugar@Pantry","10g cocoa@Pantry","5 lemons@Produce","8 mint leaves@Produce"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Big Lebowski (1998)":{"poster":"assets/menu-posters/the-big-lebowski-1998.jpg","colour":"#762a27","servings":4,"tagline":"The Dude abides. So does the White Russian.","cue":"Serve a White Russian every time the Dude makes one.","menu":{"s":[{"n":"Bowling alley nachos","note":"Corn chips with creamy cheddar sauce, mustard powder and sliced jalapeños.","how":"Warm 120ml evaporated milk gently in a saucepan. Stir in 100g grated cheddar and 1/4 tsp mustard powder until smooth, without boiling. Divide 150g corn chips between four cardboard food trays, spoon over the sauce and add 30g sliced pickled jalapeños. Serve immediately.","shop":["120ml evaporated milk@Pantry","100g cheddar@Dairy","1/4 tsp mustard powder@Pantry","150g corn chips@Pantry","30g pickled jalapeños@Pantry"]},{"n":"Rug crackers","note":"Crisp striped lavash with paprika, cumin and sesame seeds.","how":"Cut 2 lavash sheets into 12 rectangles. Brush with 1 tbsp olive oil. Sprinkle 1/2 tsp smoked paprika, 1/2 tsp ground cumin and 10g sesame seeds in alternating stripes to resemble a rug. Bake at 180°C conventional for 8 to 10 minutes until crisp. Cool before serving.","shop":["2 lavash sheets@Bakery","1 tbsp olive oil@Pantry","1/2 tsp smoked paprika@Pantry","1/2 tsp ground cumin@Pantry","10g sesame seeds@Pantry"]}],"m":[{"n":"Bowling alley burgers","note":"Double smashed beef patties with cheese, onion, pickles and crisp chips.","how":"Cut 600g potatoes into chips, rinse and dry thoroughly. Blanch in neutral oil at 140°C for 5 minutes, drain and cool 15 minutes, then fry again at 185°C for 3 minutes until crisp. Season with salt. Divide 700g beef mince into 8 loose balls. Smash thin on a hot griddle, season and cook 2 minutes per side until cooked through. Melt 120g American-style cheese over the patties. Toast 4 burger buns. Mix 60g mayonnaise, 20g tomato sauce and 10g mustard for burger sauce. Fill each bun with two patties, 1 thinly sliced onion, 80g dill pickles and sauce. Serve chips alongside.","shop":["600g potatoes@Produce","neutral oil for frying@Pantry","salt@Pantry","700g beef mince@Meat","120g American-style cheese@Dairy","4 burger buns@Bakery","60g mayonnaise@Pantry","20g tomato sauce@Pantry","10g mustard@Pantry","1 onion@Produce","80g dill pickles@Pantry"]}],"w":[{"n":"Milk and cookies","note":"Brown butter chocolate chip cookies with a glass of cold milk.","how":"Cook 80g butter over medium heat for 5 minutes until the milk solids turn golden and smell nutty. Cool until lukewarm. Mix with 80g brown sugar, 1 egg and 1/2 tsp vanilla extract. Fold in 130g plain flour, 1/4 tsp bicarbonate of soda and 80g chocolate chips. Refrigerate the dough overnight. Shape into 8 balls and bake at 180°C conventional for 11 minutes until the edges set and centres remain soft. Cool on the tray for 10 minutes. Serve two cookies each with 100ml cold full cream milk.","shop":["80g butter@Dairy","80g brown sugar@Pantry","1 egg@Dairy","1/2 tsp vanilla extract@Pantry","130g plain flour@Pantry","1/4 tsp bicarbonate of soda@Pantry","80g chocolate chips@Pantry","400ml full cream milk@Dairy"]}],"d":[{"n":"White Russian","note":"Vodka and coffee liqueur over ice, topped with thick cream.","how":"Divide 400g ice among four rocks glasses. Add 45ml vodka and 20ml coffee liqueur to each. Top each with 30ml thickened cream and stir lazily. Totals are 180ml vodka, 80ml coffee liqueur and 120ml cream. Serve one prepared drink per person.","shop":["400g ice@Frozen","180ml vodka@Bottle shop","80ml coffee liqueur@Bottle shop","120ml thickened cream@Dairy"]}],"shopping":["120ml evaporated milk@Pantry","100g cheddar@Dairy","1/4 tsp mustard powder@Pantry","150g corn chips@Pantry","30g pickled jalapeños@Pantry","2 lavash sheets@Bakery","1 tbsp olive oil@Pantry","1/2 tsp smoked paprika@Pantry","1/2 tsp ground cumin@Pantry","10g sesame seeds@Pantry","600g potatoes@Produce","neutral oil for frying@Pantry","salt@Pantry","700g beef mince@Meat","120g American-style cheese@Dairy","4 burger buns@Bakery","60g mayonnaise@Pantry","20g tomato sauce@Pantry","10g mustard@Pantry","1 onion@Produce","80g dill pickles@Pantry","80g butter@Dairy","80g brown sugar@Pantry","1 egg@Dairy","1/2 tsp vanilla extract@Pantry","130g plain flour@Pantry","1/4 tsp bicarbonate of soda@Pantry","80g chocolate chips@Pantry","400ml full cream milk@Dairy","400g ice@Frozen","180ml vodka@Bottle shop","80ml coffee liqueur@Bottle shop","120ml thickened cream@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Groundhog Day (1993)":{"poster":"assets/menu-posters/groundhog-day-1993.jpg","colour":"#2e4b64","servings":4,"tagline":"Same breakfast. Every day.","cue":"Serve the breakfast feast when Phil gorges at the diner.","menu":{"s":[{"n":"Groundhog festival doughnuts","note":"Warm cake doughnuts shaken in a paper bag with cinnamon sugar.","how":"Warm 4 small plain cake doughnuts at 160°C conventional for 2 minutes. Put 30g caster sugar and 1/2 tsp cinnamon in a clean food-safe paper bag. Add the warm doughnuts and shake gently until coated. Serve one each.","shop":["4 small cake doughnuts@Bakery","30g caster sugar@Pantry","1/2 tsp cinnamon@Pantry"]},{"n":"Ned Ryerson's eggs","note":"Boiled egg halves with creamy mustard yolks, hot sauce and paprika.","how":"Boil 4 eggs for 10 minutes, cool in iced water and peel. Halve and remove the yolks. Whip the yolks with 30g mayonnaise, 1 tsp Dijon mustard, 1/2 tsp hot sauce and 1/4 tsp smoked paprika until smooth. Pipe back into the eight white halves and refrigerate until serving.","shop":["4 eggs@Dairy","30g mayonnaise@Pantry","1 tsp Dijon mustard@Pantry","1/2 tsp hot sauce@Pantry","1/4 tsp smoked paprika@Pantry"]}],"m":[{"n":"Phil's diner feast","note":"Crisp bacon, fried eggs, pancakes, buttered toast and a slice of pie.","how":"Mix 150g plain flour, 1 tsp baking powder, 15g caster sugar, 1 egg and 200ml buttermilk into a batter. Rest 15 minutes. Render 200g bacon slowly in a frying pan over medium heat for 10 minutes until crisp and keep warm. Cook eight small pancakes in 20g butter for about 2 minutes per side until bubbles set and both sides are golden. Fry 4 eggs in the bacon pan for 3 minutes, or until the whites are set. Toast 4 slices white bread and butter with 20g butter. Warm four small 50g slices ready-baked pie at 180°C for 10 minutes. Bring everything to the table at once, with 60ml maple syrup for the pancakes.","shop":["150g plain flour@Pantry","1 tsp baking powder@Pantry","15g caster sugar@Pantry","5 eggs@Dairy","200ml buttermilk@Dairy","200g bacon@Meat","40g butter@Dairy","4 slices white bread@Bakery","200g ready-baked pie@Bakery","60ml maple syrup@Pantry"]}],"w":[{"n":"Angel food cake","note":"Light egg white sponge with fresh berries and softly whipped cream.","how":"Whisk 5 egg whites with 1/4 tsp cream of tartar to soft peaks. Gradually add 75g caster sugar and whisk until glossy. Sift 60g cake flour with 75g icing sugar, then gently fold into the whites in three additions. Spoon into an ungreased 16cm tube pan. Bake at 175°C conventional for 40 minutes until golden and springy. Invert the tin and cool upside down completely before loosening the cake. Cut into four portions and serve with 150g fresh berries and 80ml thickened cream softly whipped.","shop":["5 eggs, whites only@Dairy","1/4 tsp cream of tartar@Pantry","75g caster sugar@Pantry","60g cake flour@Pantry","75g icing sugar@Pantry","150g berries@Produce","80ml thickened cream@Dairy"]}],"d":[{"n":"Diner coffee","note":"Fresh drip coffee in thick mugs, ready for another refill.","how":"Brew 60g ground coffee with 1 litre hot water through a drip filter for about 4 minutes. Serve in four thick mugs and keep the remainder warm for refills. Put 100ml full cream milk on the table for anyone who wants it.","shop":["60g ground coffee@Pantry","100ml full cream milk@Dairy"]}],"shopping":["4 small cake doughnuts@Bakery","120g caster sugar@Pantry","1/2 tsp cinnamon@Pantry","14 eggs@Dairy","30g mayonnaise@Pantry","1 tsp Dijon mustard@Pantry","1/2 tsp hot sauce@Pantry","1/4 tsp smoked paprika@Pantry","150g plain flour@Pantry","1 tsp baking powder@Pantry","200ml buttermilk@Dairy","200g bacon@Meat","40g butter@Dairy","4 slices white bread@Bakery","200g ready-baked pie@Bakery","60ml maple syrup@Pantry","1/4 tsp cream of tartar@Pantry","60g cake flour@Pantry","75g icing sugar@Pantry","150g berries@Produce","80ml thickened cream@Dairy","60g ground coffee@Pantry","100ml full cream milk@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Dumb and Dumber (1994)":{"poster":"assets/menu-posters/dumb-and-dumber-1994.jpg","colour":"#df681c","servings":4,"tagline":"Pretty bird.","cue":"Serve the hot chilli burgers when Harry and Lloyd spike Sea Bass's burger at the truck stop.","menu":{"s":[{"n":"Mutt Cutts road snacks","note":"Potato chips, cheese puffs and dog bone pretzels for the road.","how":"Tip 60g potato chips, 60g cheese puffs and 60g dog-bone-shaped pretzels into a big shared bowl. Toss gently and share between four people for the road trip.","shop":["60g potato chips@Pantry","60g cheese puffs@Pantry","60g dog-bone-shaped pretzels@Pantry"]},{"n":"Truck stop onion rings","note":"Thick buttermilk soaked onion rings in puffed golden beer batter.","how":"Slice 2 brown onions into thick rings and soak in 150ml buttermilk for 30 minutes. Whisk 120g plain flour with 150ml cold lager and 1/4 tsp salt. Drain the onions, dip in the batter and fry in small batches in neutral oil at 185°C for 3 to 4 minutes until puffed and golden. Drain and salt lightly.","shop":["2 brown onions@Produce","150ml buttermilk@Dairy","120g plain flour@Pantry","150ml lager@Bottle shop","salt@Pantry","neutral oil for frying@Pantry"]}],"m":[{"n":"Extra hot chilli burger","note":"Beef patty with cheddar, beef chilli and pickled jalapeños.","how":"Brown 200g beef mince with 1 diced onion in 1 tsp oil for 5 minutes. Add 1 tsp chilli powder, 1/2 tsp cumin, 200g chopped tinned tomatoes and 100ml water. Simmer 25 minutes until thick and season. Shape another 500g beef mince into four patties. Griddle over medium-high heat for about 4 minutes per side until cooked through, checking 75°C at the centre. Top with 80g cheddar to melt. Toast 4 burger buns and fill with patties, chilli and 40g pickled jalapeños. Put 40ml hot sauce on the table for anyone wanting the extra-hot version.","shop":["700g beef mince@Meat","1 onion@Produce","1 tsp oil@Pantry","1 tsp chilli powder@Pantry","1/2 tsp cumin@Pantry","200g tinned tomatoes@Pantry","salt@Pantry","80g cheddar@Dairy","4 burger buns@Bakery","40g pickled jalapeños@Pantry","40ml hot sauce@Pantry"]}],"w":[{"n":"Aspen snowflake cookies","note":"Vanilla sugar cookies with white icing and silver cachous.","how":"Beat 80g softened butter with 60g caster sugar until pale. Beat in 1 egg yolk and 1/2 tsp vanilla extract, then mix in 130g plain flour. Chill 30 minutes. Roll 5mm thick and cut into 8 snowflakes. Bake at 180°C conventional for 8 minutes until pale gold at the edges. Cool completely. Mix 80g icing sugar with 2 to 3 tsp water to a spreadable white icing, coat the cookies and decorate with 10g edible silver cachous. Serve two each.","shop":["80g butter@Dairy","60g caster sugar@Pantry","1 egg, yolk only@Dairy","1/2 tsp vanilla extract@Pantry","130g plain flour@Pantry","80g icing sugar@Pantry","10g edible silver cachous@Pantry"]}],"d":[{"n":"Ski lodge hot chocolate","note":"Frothy dark chocolate milk with whipped cream and marshmallows.","how":"Heat 600ml full cream milk until steaming, without boiling. Add 100g dark chocolate and whisk until melted and frothy. Divide among four mugs. Softly whip 80ml thickened cream, spoon on top and finish with 40g marshmallows.","shop":["600ml full cream milk@Dairy","100g dark chocolate@Pantry","80ml thickened cream@Dairy","40g marshmallows@Pantry"]}],"shopping":["60g potato chips@Pantry","60g cheese puffs@Pantry","60g dog-bone-shaped pretzels@Pantry","3 brown onions@Produce","150ml buttermilk@Dairy","250g plain flour@Pantry","150ml lager@Bottle shop","salt@Pantry","neutral oil for frying and chilli@Pantry","700g beef mince@Meat","1 tsp chilli powder@Pantry","1/2 tsp cumin@Pantry","200g tinned tomatoes@Pantry","80g cheddar@Dairy","4 burger buns@Bakery","40g pickled jalapeños@Pantry","40ml hot sauce@Pantry","80g butter@Dairy","60g caster sugar@Pantry","1 egg@Dairy","1/2 tsp vanilla extract@Pantry","80g icing sugar@Pantry","10g edible silver cachous@Pantry","600ml full cream milk@Dairy","100g dark chocolate@Pantry","80ml thickened cream@Dairy","40g marshmallows@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Planes, Trains and Automobiles (1987)":{"poster":"assets/menu-posters/planes-trains-and-automobiles-1987.jpg","colour":"#85282c","servings":4,"tagline":"Three days to get home. Snacks for every leg.","cue":"Serve the snacks when Del pulls out his shower curtain rings.","menu":{"s":[{"n":"Braidwood Inn vending machine mix","note":"Salted peanuts, pretzels, chocolate and beef jerky in one shared bowl.","how":"Tip 60g salted peanuts, 60g pretzels, 60g chopped chocolate bars and 40g beef jerky into a shared bowl. Mix gently and divide between four people for the motel snack break.","shop":["60g salted peanuts@Pantry","60g pretzels@Pantry","60g chocolate bars@Pantry","40g beef jerky@Pantry"]},{"n":"Shower curtain ring onion rings","note":"Buttermilk soaked onion rings in crisp golden beer batter.","how":"Slice 2 brown onions into thick rings and soak in 150ml buttermilk for 30 minutes. Whisk 120g plain flour, 150ml cold lager and 1/4 tsp salt into a batter. Drain the rings, dip in the batter and fry in small batches in neutral oil at 185°C for 3 to 4 minutes until puffed and golden. Drain and serve hot.","shop":["2 brown onions@Produce","150ml buttermilk@Dairy","120g plain flour@Pantry","150ml lager@Bottle shop","salt@Pantry","neutral oil for frying@Pantry"]}],"m":[{"n":"Thanksgiving turkey sliders","note":"Roast turkey with cranberry, baked stuffing and gravy in soft buns.","how":"Dissolve 30g salt in 1 litre cold water. Submerge 700g turkey breast and refrigerate for 6 hours. Drain, pat dry and roast at 170°C conventional for about 50 to 60 minutes, until the centre reaches 70°C and stays at that temperature for 2 minutes. Rest 15 minutes and slice. Prepare 150g stuffing mix with the packet's water amount, spread in a small baking dish and bake beside the turkey for 25 minutes, then cut into 8 squares. Make gravy by melting 20g butter, stirring in 20g flour for 1 minute and whisking in 300ml chicken stock; simmer 5 minutes. Fill 8 soft slider buns with turkey, 80g cranberry sauce, stuffing squares and a spoonful of gravy. Serve two each.","shop":["700g turkey breast@Meat","30g salt@Pantry","150g stuffing mix@Pantry","20g butter@Dairy","20g plain flour@Pantry","300ml chicken stock@Pantry","8 soft slider buns@Bakery","80g cranberry sauce@Pantry"]}],"w":[{"n":"Thanksgiving pumpkin pie","note":"Spiced roast pumpkin custard in pastry, served with whipped cream.","how":"Roast 450g peeled pumpkin at 200°C conventional for 30 minutes until soft, then purée and measure 300g. Line a 20cm pie dish with 250g sweet shortcrust pastry. Blind-bake with baking paper and weights at 180°C for 15 minutes, remove the weights and bake 5 minutes more. Whisk the pumpkin purée with 2 eggs, 80g brown sugar, 100ml thickened cream, 1/2 tsp cinnamon, 1/4 tsp ground ginger and 1/8 tsp nutmeg. Pour into the crust and bake at 170°C for 50 minutes until just set. Cool, then serve four portions with another 100ml cream softly whipped.","shop":["450g peeled pumpkin@Produce","250g sweet shortcrust pastry@Frozen","2 eggs@Dairy","80g brown sugar@Pantry","200ml thickened cream@Dairy","1/2 tsp cinnamon@Pantry","1/4 tsp ground ginger@Pantry","1/8 tsp nutmeg@Pantry"]}],"d":[{"n":"Del's airport beer","note":"Ice cold American lager for a toast to getting home.","how":"Chill four 375ml bottles of American lager for at least 2 hours. Open just before serving and raise a toast to finally getting home.","shop":["4 x 375ml American lager@Bottle shop"]}],"shopping":["60g salted peanuts@Pantry","60g pretzels@Pantry","60g chocolate bars@Pantry","40g beef jerky@Pantry","2 brown onions@Produce","150ml buttermilk@Dairy","160g plain flour@Pantry","150ml lager for batter@Bottle shop","salt, including 30g for brine@Pantry","neutral oil for frying@Pantry","700g turkey breast@Meat","150g stuffing mix@Pantry","20g butter@Dairy","300ml chicken stock@Pantry","8 soft slider buns@Bakery","80g cranberry sauce@Pantry","450g peeled pumpkin@Produce","250g sweet shortcrust pastry@Frozen","2 eggs@Dairy","80g brown sugar@Pantry","200ml thickened cream@Dairy","1/2 tsp cinnamon@Pantry","1/4 tsp ground ginger@Pantry","1/8 tsp nutmeg@Pantry","4 x 375ml American lager@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Pretty in Pink (1986)":{"poster":"assets/menu-posters/pretty-in-pink-1986.jpg","colour":"#b63269","servings":4,"tagline":"Pink lemonade. Obviously.","cue":"Serve the snacks when Duckie dances on the record shop counter.","menu":{"s":[{"n":"Trax record shop snacks","note":"Salted pretzels, red liquorice and pink sugared almonds in mismatched bowls.","how":"Tip 80g salted pretzels, 80g red liquorice and 80g pink sugared almonds into three mismatched bowls. Arrange beside the record player and share between four people.","shop":["80g salted pretzels@Pantry","80g red liquorice@Pantry","80g pink sugared almonds@Pantry"]},{"n":"Duckie's dance-off popcorn","note":"Crisp popcorn in pink white chocolate with freeze dried raspberry.","how":"Pop 50g popcorn kernels in 1 tbsp neutral oil in a covered pot over medium heat for 3 to 4 minutes, shaking regularly. Melt 80g white chocolate gently. Crush 10g freeze-dried raspberries to a powder and stir into the chocolate to tint it pink. Toss through the popcorn, spread on a lined tray and leave 20 minutes to set.","shop":["50g popcorn kernels@Pantry","1 tbsp neutral oil@Pantry","80g white chocolate@Pantry","10g freeze-dried raspberries@Pantry"]}],"m":[{"n":"Andie's dad's pot roast","note":"Slow braised beef with onion, carrot, garlic, potatoes and rich stock.","how":"Season 900g beef chuck roast with 1 tsp salt and 1/2 tsp black pepper. Brown all sides in 1 tbsp neutral oil in a heavy casserole for 8 minutes. Add 2 quartered brown onions, 3 chopped carrots, 4 garlic cloves and 500ml beef stock. Cover and braise at 160°C conventional for 3 hours. After 2 hours add 600g peeled potato chunks, cover and cook for the final hour until the beef and potatoes are tender. Rest the beef 15 minutes, slice or pull apart and serve with the vegetables and rich stock.","shop":["900g beef chuck roast@Meat","salt@Pantry","black pepper@Pantry","1 tbsp neutral oil@Pantry","2 brown onions@Produce","3 carrots@Produce","4 garlic cloves@Produce","500ml beef stock@Pantry","600g potatoes@Produce"]}],"w":[{"n":"Two-dress prom cake","note":"Vanilla and strawberry sponge joined with pink and white buttercream.","how":"Heat the oven to 180°C conventional and line two 12cm round tins. Cook 100g chopped strawberries over low heat for 8 minutes until reduced to about 30g thick purée; cool. Beat 120g softened butter with 120g caster sugar until pale. Beat in 2 eggs, then fold in 140g self-raising flour. Divide the batter equally. Stir 1/2 tsp vanilla into one half and the strawberry purée into the other. Bake side by side for 20 to 25 minutes until a skewer comes out clean. Cool, cut both cakes in half and join one vanilla and one strawberry semicircle using buttercream. Save the spare halves or use them for a second layer. Beat 80g softened butter with 160g icing sugar and 1 tsp milk. Tint half pink. Cover half the cake pink and half white, piping a seam along the join. Cut four portions.","shop":["100g strawberries@Produce","200g butter@Dairy","120g caster sugar@Pantry","2 eggs@Dairy","140g self-raising flour@Pantry","1/2 tsp vanilla extract@Pantry","160g icing sugar@Pantry","1 tsp milk@Dairy","pink food colouring@Pantry"]}],"d":[{"n":"Pink lemonade","note":"Fresh lemon, sugar syrup and raspberry purée over plenty of ice.","how":"Dissolve 80g caster sugar in 80ml hot water and cool to make syrup. Purée 80g raspberries and strain if desired. Mix the syrup with 120ml fresh lemon juice and 600ml cold water, then stir in the raspberry purée. Divide among four glasses with 400g ice.","shop":["80g caster sugar@Pantry","80g raspberries@Produce","4 lemons for 120ml juice@Produce","400g ice@Frozen"]}],"shopping":["80g salted pretzels@Pantry","80g red liquorice@Pantry","80g pink sugared almonds@Pantry","50g popcorn kernels@Pantry","2 tbsp neutral oil@Pantry","80g white chocolate@Pantry","10g freeze-dried raspberries@Pantry","900g beef chuck roast@Meat","salt@Pantry","black pepper@Pantry","2 brown onions@Produce","3 carrots@Produce","4 garlic cloves@Produce","500ml beef stock@Pantry","600g potatoes@Produce","100g strawberries@Produce","200g butter@Dairy","200g caster sugar@Pantry","2 eggs@Dairy","140g self-raising flour@Pantry","1/2 tsp vanilla extract@Pantry","160g icing sugar@Pantry","1 tsp milk@Dairy","pink food colouring@Pantry","80g raspberries@Produce","4 lemons@Produce","400g ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Breakfast Club (1985)":{"poster":"assets/menu-posters/the-breakfast-club-1985.jpg","colour":"#87322d","servings":4,"tagline":"Five strangers. One detention. Plenty of snacks.","cue":"Serve the snacks when everyone unpacks their lunch.","menu":{"s":[{"n":"Andrew's lunch bag","note":"Ham and cheese sandwiches, potato chips, apples and cold milk.","how":"Make three ham and cheese sandwiches using 6 slices white bread, 120g leg ham and 90g cheddar. Cut each sandwich into four small pieces. Put three pieces in each of four paper bags, along with 20g potato chips and one quarter of each of 2 sliced apples. Serve 100ml cold full cream milk per person in small cartons or glasses.","shop":["6 slices white bread@Bakery","120g leg ham@Deli","90g cheddar@Dairy","80g potato chips@Pantry","2 apples@Produce","400ml full cream milk@Dairy"]},{"n":"Bender's share plate","note":"Crackers, cheese and salami for anyone who forgot their lunch.","how":"Arrange 80g crackers, 100g cubed cheddar and 80g sliced salami on a shared plate in the middle of the table. Let everyone help themselves.","shop":["80g crackers@Pantry","100g cheddar@Dairy","80g salami@Deli"]}],"m":[{"n":"Brian's lunch","note":"Roasted tomato soup with cream, plus crustless peanut butter and jam sandwiches.","how":"Halve 800g tomatoes and put in a roasting dish with 1 quartered brown onion, 3 garlic cloves and 1 tbsp olive oil. Roast at 200°C conventional for 35 minutes until softened and browned. Transfer to a pot with 500ml chicken stock and simmer 10 minutes. Blitz smooth with 80ml thickened cream and season with salt and pepper. Pour into four warmed thermoses. Make four peanut butter and jam sandwiches with 8 slices white bread, 80g peanut butter and 60g jam; cut off the crusts and serve with the soup.","shop":["800g tomatoes@Produce","1 brown onion@Produce","3 garlic cloves@Produce","1 tbsp olive oil@Pantry","500ml chicken stock@Pantry","80ml thickened cream@Dairy","salt and pepper@Pantry","8 slices white bread@Bakery","80g peanut butter@Pantry","60g jam@Pantry"]}],"w":[{"n":"Detention brownies","note":"Fudgy dark chocolate brownies with a soft centre and crisp edges.","how":"Melt 100g dark chocolate with 100g butter gently and cool slightly. Whisk in 120g caster sugar and 2 eggs. Fold in 60g plain flour and a pinch of salt. Pour into a lined 18cm square tin and bake at 175°C conventional for 25 minutes until the edges are set and the middle still gently wobbles. Cool at least 30 minutes before cutting into four portions.","shop":["100g dark chocolate@Pantry","100g butter@Dairy","120g caster sugar@Pantry","2 eggs@Dairy","60g plain flour@Pantry","salt@Pantry"]}],"d":[{"n":"Andrew's carton of milk","note":"Cold full cream milk, plain or mixed with cocoa and sugar.","how":"Serve 200ml cold full cream milk per person in four small cartons or glasses. For chocolate milk, dissolve 20g cocoa and 25g caster sugar in 100ml hot milk, cool, then mix with 700ml cold milk and divide among four glasses. Use the same total 800ml milk for either version.","shop":["800ml full cream milk@Dairy","20g cocoa, optional@Pantry","25g caster sugar, optional@Pantry"]}],"shopping":["14 slices white bread@Bakery","120g leg ham@Deli","190g cheddar@Dairy","80g potato chips@Pantry","2 apples@Produce","1.2 litres full cream milk@Dairy","80g crackers@Pantry","80g salami@Deli","800g tomatoes@Produce","1 brown onion@Produce","3 garlic cloves@Produce","1 tbsp olive oil@Pantry","500ml chicken stock@Pantry","80ml thickened cream@Dairy","salt and pepper@Pantry","80g peanut butter@Pantry","60g jam@Pantry","100g dark chocolate@Pantry","100g butter@Dairy","145g caster sugar, includes optional drink@Pantry","2 eggs@Dairy","60g plain flour@Pantry","20g cocoa, optional@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Aliens (1986)":{"poster":"assets/menu-posters/aliens-1986.jpg","colour":"#28525b","servings":4,"tagline":"Game over, man. Dinner's on.","cue":"Serve the snacks at the marines' breakfast on the Sulaco.","menu":{"s":[{"n":"Sulaco mess hall cornbread","note":"Golden buttermilk cornbread baked in a hot buttered pan.","how":"Heat the oven to 200°C conventional with a 20cm ovenproof skillet inside. Mix 100g fine cornmeal, 80g plain flour, 20g caster sugar, 1 tsp baking powder and 1/4 tsp salt. Whisk 150ml buttermilk, 1 egg and 30g melted butter, then stir into the dry ingredients. Carefully butter the hot skillet with 10g butter, pour in the batter and bake for 20 minutes until golden and a skewer comes out clean. Cool 5 minutes and cut into 8 squares.","shop":["100g fine cornmeal@Pantry","80g plain flour@Pantry","20g caster sugar@Pantry","1 tsp baking powder@Pantry","salt@Pantry","150ml buttermilk@Dairy","1 egg@Dairy","40g butter@Dairy"]},{"n":"Bishop's knife trick breadsticks","note":"Long crisp dough sticks brushed with oil, sesame and salt.","how":"Roll 250g pizza dough into 12 long thin sticks. Place on a lined tray, brush with 1 tbsp extra virgin olive oil and roll in 15g sesame seeds and 1/2 tsp sea salt flakes. Bake at 220°C conventional for 12 minutes until crisp and golden. Cool slightly before serving.","shop":["250g pizza dough@Bakery","1 tbsp extra virgin olive oil@Pantry","15g sesame seeds@Pantry","1/2 tsp sea salt flakes@Pantry"]}],"m":[{"n":"Sulaco mess hall meatloaf","note":"Beef and pork loaf with tomato glaze and creamy mashed potato.","how":"Soak 50g breadcrumbs in 80ml milk for 5 minutes. Mix with 350g beef mince, 250g pork mince, 1 egg, 1 finely diced onion, 1 tbsp anchovy-free Worcestershire sauce, 1/2 tsp salt and 1/4 tsp black pepper. Shape into a loaf on a lined tray and glaze with 60g tomato sauce. Bake at 180°C conventional for 1 hour until cooked through, at least 75°C in the centre. Rest 10 minutes. Meanwhile peel and chop 800g potatoes, boil 20 minutes until tender and mash with 40g butter and 100ml warm milk. Slice the loaf and serve with mash.","shop":["50g breadcrumbs@Pantry","180ml milk@Dairy","350g beef mince@Meat","250g pork mince@Meat","1 egg@Dairy","1 onion@Produce","1 tbsp anchovy-free Worcestershire sauce@Pantry","salt@Pantry","black pepper@Pantry","60g tomato sauce@Pantry","800g potatoes@Produce","40g butter@Dairy"]}],"w":[{"n":"Facehugger panna cotta","note":"Wobbly vanilla cream with candied orange peel strips fanned around it.","how":"Soak 4g gelatine leaves, using the packet's equivalent weight, in cold water for 5 minutes. Warm 250ml thickened cream, 150ml full cream milk, 40g caster sugar and seeds of half a vanilla bean over low heat until steaming, without boiling. Remove from heat, squeeze the gelatine dry and stir in until dissolved. Divide into four lightly oiled 100ml round moulds and refrigerate at least 4 hours until set. Dip each mould briefly in warm water and turn out. Fan 40g candied orange peel strips around the puddings as legs.","shop":["4g gelatine leaves@Pantry","250ml thickened cream@Dairy","150ml full cream milk@Dairy","40g caster sugar@Pantry","1/2 vanilla bean@Pantry","neutral oil for moulds@Pantry","40g candied orange peel@Pantry"]}],"d":[{"n":"Marine strength coffee","note":"Strong black drip coffee served in plain steel mess mugs.","how":"Brew 70g ground coffee with 800ml hot water through a drip filter for about 4 minutes. Divide the strong black coffee among four steel mugs and serve hot.","shop":["70g ground coffee@Pantry"]}],"shopping":["100g fine cornmeal@Pantry","80g plain flour@Pantry","60g caster sugar@Pantry","1 tsp baking powder@Pantry","salt@Pantry","150ml buttermilk@Dairy","2 eggs@Dairy","80g butter@Dairy","250g pizza dough@Bakery","1 tbsp extra virgin olive oil@Pantry","15g sesame seeds@Pantry","1/2 tsp sea salt flakes@Pantry","50g breadcrumbs@Pantry","330ml full cream milk@Dairy","350g beef mince@Meat","250g pork mince@Meat","1 onion@Produce","1 tbsp anchovy-free Worcestershire sauce@Pantry","black pepper@Pantry","60g tomato sauce@Pantry","800g potatoes@Produce","4g gelatine leaves@Pantry","250ml thickened cream@Dairy","1/2 vanilla bean@Pantry","neutral oil for moulds@Pantry","40g candied orange peel@Pantry","70g ground coffee@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Back to the Future (1985)":{"poster":"assets/menu-posters/back-to-the-future-1985.jpg","colour":"#265b7e","servings":4,"tagline":"Great Scott, that's a good burger.","cue":"Serve the mains when Marty walks into Lou's Cafe in 1955 and asks for a sugar-free drink.","menu":{"s":[{"n":"Lou's Cafe fries","note":"Hand cut chips, double fried until crisp and lightly salted.","how":"Hand-cut 500g potatoes into chips, rinse and dry thoroughly. Heat vegetable oil in a sturdy deep pan to 140°C. Blanch the chips in batches for 5 minutes without browning, drain and cool 15 minutes. Increase the oil to 185°C and fry for 2 to 3 minutes until crisp. Drain, season with 1/2 tsp fine salt and serve in red-checked food-safe paper boats.","shop":["500g potatoes@Produce","vegetable oil for frying@Pantry","1/2 tsp fine salt@Pantry"]},{"n":"Clock tower cheese straws","note":"Tall twisted pastry strips with cheddar, parmesan and a little cayenne.","how":"Brush 1 sheet puff pastry with half of 1 beaten egg. Scatter over 60g grated cheddar, 20g grated parmesan and 1/8 tsp cayenne pepper. Fold in half and press lightly. Cut into 8 tall strips, twist each and place on a lined tray. Brush with the remaining egg. Bake at 220°C conventional for 12 minutes until puffed and golden.","shop":["1 sheet puff pastry@Frozen","1 egg@Dairy","60g cheddar@Dairy","20g parmesan@Dairy","1/8 tsp cayenne pepper@Pantry"]}],"m":[{"n":"Lou's malt shop cheeseburger","note":"Smashed onion beef patty with cheese, pickles and mustard.","how":"Divide 600g beef mince into four loose balls. Slice 1 onion very thin. Heat a griddle until hot. Put the beef balls on the griddle, top with the onions and press firmly into thin patties. Season with 1/2 tsp salt and 1/4 tsp black pepper. Cook 3 minutes, flip and cook 2 to 3 minutes until cooked through, checking the centre reaches 75°C. Add 80g American-style cheese to melt. Toast 4 burger buns and fill with the patties, 60g sliced dill pickles and 30g yellow mustard.","shop":["600g beef mince@Meat","1 onion@Produce","salt@Pantry","black pepper@Pantry","80g American-style cheese@Dairy","4 burger buns@Bakery","60g dill pickles@Pantry","30g yellow mustard@Pantry"]}],"w":[{"n":"Enchantment Under the Sea cupcakes","note":"Vanilla cupcakes with ocean blue buttercream, sugar pearls and gummy fish.","how":"Beat 80g softened butter with 80g caster sugar until pale. Beat in 1 egg and 1 tsp vanilla extract. Fold in 100g self-raising flour and 40ml milk. Divide among 8 cupcake cases and bake at 180°C conventional for 18 minutes until a skewer comes out clean. Cool completely. Beat 60g softened butter with 120g icing sugar and 1 tsp milk until fluffy. Tint with a little blue food colouring, pipe on the cakes and top with 10g sugar pearls and 8 fish-shaped gummy sweets. Serve two small cupcakes each.","shop":["140g butter@Dairy","80g caster sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","100g self-raising flour@Pantry","45ml milk@Dairy","120g icing sugar@Pantry","blue food colouring@Pantry","10g sugar pearls@Pantry","8 fish-shaped gummy sweets@Pantry"]}],"d":[{"n":"Chocolate malt","note":"Thick vanilla ice cream blend with chocolate syrup and malted milk.","how":"Blend 600ml vanilla ice cream, 400ml full cream milk, 4 tbsp chocolate syrup and 4 tbsp malted milk powder until thick and smooth. Divide among four chilled glasses and serve immediately with straws.","shop":["600ml vanilla ice cream@Frozen","400ml full cream milk@Dairy","4 tbsp chocolate syrup@Drinks","4 tbsp malted milk powder@Pantry"]}],"shopping":["500g potatoes@Produce","vegetable oil for frying@Pantry","fine salt@Pantry","1 sheet puff pastry@Frozen","2 eggs@Dairy","60g cheddar@Dairy","20g parmesan@Dairy","1/8 tsp cayenne pepper@Pantry","600g beef mince@Meat","1 onion@Produce","black pepper@Pantry","80g American-style cheese@Dairy","4 burger buns@Bakery","60g dill pickles@Pantry","30g yellow mustard@Pantry","140g butter@Dairy","80g caster sugar@Pantry","1 tsp vanilla extract@Pantry","100g self-raising flour@Pantry","445ml full cream milk@Dairy","120g icing sugar@Pantry","blue food colouring@Pantry","10g sugar pearls@Pantry","8 fish-shaped gummy sweets@Pantry","600ml vanilla ice cream@Frozen","4 tbsp chocolate syrup@Drinks","4 tbsp malted milk powder@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Running Scared (1986)":{"poster":"assets/menu-posters/running-scared-1986.jpg","colour":"#285574","servings":4,"tagline":"Two Chicago cops. One more week.","cue":"Serve the mains when they daydream about Key West.","menu":{"s":[{"n":"Chicago hot dogs","note":"Beef franks with mustard, relish, onion, tomato, pickles and celery salt.","how":"Heat 4 small all-beef franks in simmering water for 5 minutes until piping hot. Warm 4 small poppy seed hot dog buns in a steamer for 1 minute. Add the franks and divide 20g yellow mustard, 30g sweet relish, half a diced onion, 1 sliced tomato, 4 pickle spears and 8 sport peppers among the buns. Finish with 1/4 tsp celery salt. Serve one small hot dog each.","shop":["4 small all-beef franks@Meat","4 small poppy seed hot dog buns@Bakery","20g yellow mustard@Pantry","30g sweet relish@Pantry","1/2 onion@Produce","1 tomato@Produce","4 pickle spears@Pantry","8 sport peppers@Pantry","1/4 tsp celery salt@Pantry"]},{"n":"El train pretzels","note":"Warm soft pretzels brushed with butter, coarse salt and yellow mustard.","how":"Brush 4 small soft pretzels with 25g melted butter and sprinkle with 1/2 tsp coarse salt. Warm at 200°C conventional for 5 minutes. Serve with 30g yellow mustard on the side.","shop":["4 small soft pretzels@Bakery","25g butter@Dairy","1/2 tsp coarse salt@Pantry","30g yellow mustard@Pantry"]}],"m":[{"n":"Chicago Italian beef","note":"Thin roast beef in garlic oregano jus, dipped rolls and hot giardiniera.","how":"Season 800g beef topside with 1 tsp salt and 1/2 tsp black pepper. Roast at 200°C conventional for about 40 minutes, checking with a thermometer, until 52°C at the centre for rare. Rest 20 minutes. Simmer 400ml beef stock with 3 crushed garlic cloves and 1 tsp dried oregano for 10 minutes to make jus. Shave the rested beef very thin and warm gently in the jus for 1 minute. Pile into 4 long rolls, dip briefly in the jus and top with 100g hot giardiniera.","shop":["800g beef topside@Meat","salt@Pantry","black pepper@Pantry","400ml beef stock@Pantry","3 garlic cloves@Produce","1 tsp dried oregano@Pantry","4 long rolls@Bakery","100g hot giardiniera@Pantry"]}],"w":[{"n":"Key lime pie","note":"Biscuit crust with baked lime custard and chilled whipped cream.","how":"Crush 150g digestive biscuits and mix with 60g melted butter. Press into a 20cm pie dish. Whisk 400g condensed milk, 4 egg yolks and 120ml lime juice until smooth, then pour into the crust. Bake at 160°C conventional for 15 minutes until just set. Cool and chill for at least 4 hours. Softly whip 100ml thickened cream, spoon over the pie and divide into four generous portions.","shop":["150g digestive biscuits@Pantry","60g butter@Dairy","400g condensed milk@Pantry","4 eggs, yolks only@Dairy","5 limes for 120ml juice@Produce","100ml thickened cream@Dairy"]}],"d":[{"n":"Key West rum punch","note":"Rum, pineapple, orange and lime over ice with grenadine and nutmeg.","how":"Fill four glasses with 400g ice. For each drink add 45ml golden rum, 30ml pineapple juice, 30ml orange juice, 15ml lime juice and 5ml grenadine. Stir and finish with a light grating of nutmeg. Totals are 180ml rum, 120ml each pineapple and orange juice, 60ml lime juice and 20ml grenadine.","shop":["400g ice@Frozen","180ml golden rum@Bottle shop","120ml pineapple juice@Drinks","120ml orange juice@Drinks","2 limes for 60ml juice@Produce","20ml grenadine@Drinks","ground or whole nutmeg@Pantry"]}],"shopping":["4 small all-beef franks@Meat","4 small poppy seed hot dog buns@Bakery","50g yellow mustard@Pantry","30g sweet relish@Pantry","1 onion, use half@Produce","1 tomato@Produce","4 pickle spears@Pantry","8 sport peppers@Pantry","1/4 tsp celery salt@Pantry","4 small soft pretzels@Bakery","85g butter@Dairy","coarse and fine salt@Pantry","800g beef topside@Meat","black pepper@Pantry","400ml beef stock@Pantry","3 garlic cloves@Produce","1 tsp dried oregano@Pantry","4 long rolls@Bakery","100g hot giardiniera@Pantry","150g digestive biscuits@Pantry","400g condensed milk@Pantry","4 eggs@Dairy","7 limes@Produce","100ml thickened cream@Dairy","400g ice@Frozen","180ml golden rum@Bottle shop","120ml pineapple juice@Drinks","120ml orange juice@Drinks","20ml grenadine@Drinks","nutmeg@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Rush Hour (1998)":{"poster":"assets/menu-posters/rush-hour-1998.jpg","colour":"#a52624","servings":4,"tagline":"Two cops. One case. Several misunderstandings.","cue":"Serve the mains when Lee walks into the Foo Chow restaurant.","menu":{"s":[{"n":"Consulate spring rolls","note":"Crisp pastry rolls with cabbage, carrot, shiitake and glass noodles.","how":"Soak 30g glass noodles in hot water for 5 minutes, drain and cut short. Stir-fry 120g shredded cabbage, 1 grated carrot and 60g finely sliced shiitake in 1 tsp oil for 4 minutes. Add the noodles and 1 tsp light soy sauce, stir 1 minute and cool completely. Divide among 8 spring roll pastry sheets, roll tightly and seal with a paste of 1 tsp flour and 1 tsp water. Fry in neutral oil at 180°C for 3 to 4 minutes until golden. Serve with 40ml sweet chilli sauce.","shop":["30g glass noodles@Pantry","120g cabbage@Produce","1 carrot@Produce","60g shiitake@Produce","neutral oil for frying@Pantry","1 tsp light soy sauce@Pantry","8 spring roll pastry sheets@Frozen","1 tsp plain flour@Pantry","40ml sweet chilli sauce@Pantry"]},{"n":"Carter's hot wings","note":"Crisp baked wings in hot butter sauce with cooling ranch dip.","how":"Pat 600g chicken wings dry and season with 1/2 tsp salt. Bake on a rack at 220°C conventional for 45 minutes, turning halfway, until crisp and at least 74°C inside. Melt 25g butter and mix with 35ml hot sauce; toss through the wings. For a cooling ranch dip, mix 80g sour cream, 20g mayonnaise, 1 tbsp chopped chives, 1/4 tsp garlic powder and 1 tsp lemon juice. Serve beside the wings.","shop":["600g chicken wings@Meat","salt@Pantry","25g butter@Dairy","35ml hot sauce@Pantry","80g sour cream@Dairy","20g mayonnaise@Pantry","1 tbsp chives@Produce","1/4 tsp garlic powder@Pantry","1 tsp lemon juice@Produce"]}],"m":[{"n":"Foo Chow noodles","note":"Wide rice noodles wok fried with beef, sprouts and spring onion.","how":"Thinly slice 400g beef rump and marinate for 20 minutes with 1 tbsp light soy sauce, 1 tsp cornflour and 1 tsp sesame oil. Separate 600g fresh wide rice noodles gently. Heat 1 tbsp neutral oil in a wok over high heat; stir-fry the beef in two batches for 2 minutes and set aside. Add another 1 tbsp oil and fry the noodles for 2 minutes. Add 150g bean sprouts, 3 sliced spring onions, 1 tbsp dark soy sauce and 1 tbsp light soy sauce. Return the beef and toss over high heat for 2 minutes until piping hot. Serve immediately.","shop":["400g beef rump@Meat","2 tbsp light soy sauce@Pantry","1 tsp cornflour@Pantry","1 tsp sesame oil@Pantry","600g fresh wide rice noodles@Pantry","2 tbsp neutral oil@Pantry","150g bean sprouts@Produce","3 spring onions@Produce","1 tbsp dark soy sauce@Pantry"]}],"w":[{"n":"Fortune cookies","note":"Thin vanilla cookies folded around paper fortunes while still hot.","how":"Write 8 fortunes on small clean food-safe paper strips. Whisk 2 egg whites with 50g caster sugar until foamy. Stir in 25g melted butter, 40g plain flour, 1/2 tsp vanilla extract and 1 tbsp water. Spread two thin 10cm circles at a time on a lined tray. Bake at 180°C conventional for 6 minutes until the edges turn golden. Working quickly while hot, place a fortune in each, fold in half and bend over a mug rim into the classic shape. Cool in muffin-tin cups. Repeat for 8 cookies. Remind everyone to remove the paper before eating.","shop":["2 eggs, whites only@Dairy","50g caster sugar@Pantry","25g butter@Dairy","40g plain flour@Pantry","1/2 tsp vanilla extract@Pantry"]}],"d":[{"n":"Chinese lager","note":"Ice cold Chinese pale lager, or freshly brewed jasmine tea.","how":"Chill four 330ml bottles of Chinese pale lager for at least 2 hours. For the tea option, steep 8g jasmine tea in 800ml water at 80°C for 3 minutes, strain and divide among four cups.","shop":["4 x 330ml Chinese pale lager@Bottle shop","8g jasmine tea, optional alternative@Pantry"]}],"shopping":["30g glass noodles@Pantry","120g cabbage@Produce","1 carrot@Produce","60g shiitake@Produce","neutral oil for frying and wok cooking@Pantry","2 tbsp plus 1 tsp light soy sauce@Pantry","8 spring roll pastry sheets@Frozen","43g plain flour@Pantry","40ml sweet chilli sauce@Pantry","600g chicken wings@Meat","salt@Pantry","50g butter@Dairy","35ml hot sauce@Pantry","80g sour cream@Dairy","20g mayonnaise@Pantry","1 tbsp chives@Produce","1/4 tsp garlic powder@Pantry","1 lemon, use 1 tsp juice@Produce","400g beef rump@Meat","1 tsp cornflour@Pantry","1 tsp sesame oil@Pantry","600g fresh wide rice noodles@Pantry","150g bean sprouts@Produce","3 spring onions@Produce","1 tbsp dark soy sauce@Pantry","2 eggs@Dairy","50g caster sugar@Pantry","1/2 tsp vanilla extract@Pantry","4 x 330ml Chinese pale lager@Bottle shop","8g jasmine tea, optional alternative@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Bad Boys (1995)":{"poster":"assets/menu-posters/bad-boys-1995.jpg","colour":"#23696e","servings":4,"tagline":"Whatcha gonna eat?","cue":"Serve dinner when Marcus has to pretend to be Mike.","menu":{"s":[{"n":"Miami croquetas","note":"Crisp crumbed ham croquettes with thick béchamel and a little nutmeg.","how":"Melt 30g butter, stir in 40g plain flour and cook 2 minutes. Gradually whisk in 250ml full cream milk and cook 5 minutes until a very thick béchamel forms. Stir in 120g finely chopped leg ham and 1/8 tsp nutmeg. Spread in a shallow dish, cool promptly and refrigerate overnight. Shape into 8 logs. Dust with 20g flour, dip in 1 beaten egg and coat in 60g breadcrumbs. Fry in neutral oil at 180°C for 3 to 4 minutes until golden and hot throughout. Drain and serve two each.","shop":["30g butter@Dairy","60g plain flour@Pantry","250ml full cream milk@Dairy","120g leg ham@Deli","1/8 tsp nutmeg@Pantry","1 egg@Dairy","60g breadcrumbs@Pantry","neutral oil for frying@Pantry"]},{"n":"Fried sweet plantains","note":"Caramelised ripe plantain slices, soft inside with a flaky salt finish.","how":"Peel 2 very ripe plantains and cut diagonally into 1cm slices. Heat 3 tbsp vegetable oil in a frying pan over medium heat. Fry the slices in batches for 3 minutes each side until caramelised and soft. Drain and finish with 1/4 tsp sea salt flakes.","shop":["2 very ripe plantains@Produce","3 tbsp vegetable oil@Pantry","1/4 tsp sea salt flakes@Pantry"]}],"m":[{"n":"Miami Cuban sandwich","note":"Pressed bread with mojo pork, ham, Swiss, mustard and pickles.","how":"Marinate 700g boneless pork shoulder overnight with juice of 1 orange and 1 lime, 3 crushed garlic cloves, 1 tsp oregano, 1 tsp cumin and 1/2 tsp salt. Put in a covered roasting dish with 100ml water and roast at 160°C conventional for about 3 hours until tender; rest 20 minutes and shred. Split 4 long soft rolls and spread with 40g yellow mustard. Fill with the pork, 120g leg ham, 120g Swiss cheese and 80g sliced dill pickles. Butter the outsides with 30g butter and press in a hot sandwich press for 5 minutes, until crisp and flat and the filling is piping hot.","shop":["700g boneless pork shoulder@Meat","1 orange@Produce","1 lime@Produce","3 garlic cloves@Produce","1 tsp oregano@Pantry","1 tsp cumin@Pantry","salt@Pantry","4 long soft rolls@Bakery","40g yellow mustard@Pantry","120g leg ham@Deli","120g Swiss cheese@Dairy","80g dill pickles@Pantry","30g butter@Dairy"]}],"w":[{"n":"Key lime pie","note":"Biscuit crust, lime custard and a cool whipped cream topping.","how":"Crush 150g digestive biscuits, mix with 60g melted butter and press into a 20cm pie dish. Bake at 180°C conventional for 10 minutes. Whisk 400g condensed milk with 4 egg yolks, 120ml lime juice and zest of 2 limes. Pour into the crust and bake at 160°C for 15 minutes until just set. Cool and refrigerate for at least 4 hours. Softly whip 100ml thickened cream and spread over the pie. Cut four generous portions.","shop":["150g digestive biscuits@Pantry","60g butter@Dairy","400g condensed milk@Pantry","4 eggs, yolks only@Dairy","5 limes for 120ml juice and zest@Produce","100ml thickened cream@Dairy"]}],"d":[{"n":"Mojito","note":"Mint, lime, white rum and soda over plenty of crushed ice.","how":"Gently muddle 24 mint leaves with 60ml sugar syrup and 60ml lime juice in a jug, avoiding shredding the mint. Add 180ml white rum. Divide between four glasses filled with 500g crushed ice. Top with 400ml soda water and stir gently. Garnish with 4 mint sprigs.","shop":["24 mint leaves and 4 sprigs@Produce","60ml sugar syrup@Drinks","2 limes for 60ml juice@Produce","180ml white rum@Bottle shop","500g crushed ice@Frozen","400ml soda water@Drinks"]}],"shopping":["120g butter@Dairy","60g plain flour@Pantry","250ml full cream milk@Dairy","240g leg ham@Deli","1/8 tsp nutmeg@Pantry","5 eggs@Dairy","60g breadcrumbs@Pantry","neutral vegetable oil for frying@Pantry","2 very ripe plantains@Produce","1/4 tsp sea salt flakes@Pantry","700g boneless pork shoulder@Meat","1 orange@Produce","8 limes@Produce","3 garlic cloves@Produce","1 tsp oregano@Pantry","1 tsp cumin@Pantry","salt@Pantry","4 long soft rolls@Bakery","40g yellow mustard@Pantry","120g Swiss cheese@Dairy","80g dill pickles@Pantry","150g digestive biscuits@Pantry","400g condensed milk@Pantry","100ml thickened cream@Dairy","24 mint leaves and 4 sprigs@Produce","60ml sugar syrup@Drinks","180ml white rum@Bottle shop","500g crushed ice@Frozen","400ml soda water@Drinks"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Tango & Cash (1989)":{"poster":"assets/menu-posters/tango-and-cash-1989.jpg","colour":"#214fc0","servings":4,"tagline":"Two cops. One shower. Zero patience.","cue":"Serve the mains when the armoured RV rolls out.","menu":{"s":[{"n":"Prison canteen sandwiches","note":"Crisp butter griddled white bread with devon, cheese and mustard.","how":"Spread 8 slices white bread with 20g yellow mustard. Layer 120g devon and 80g American-style cheese between the slices to make four sandwiches. Butter the outside using 30g softened butter. Griddle over medium heat under a weighted pan for 3 minutes each side until crisp and the cheese melts. Cut each into fingers to share.","shop":["8 slices white bread@Bakery","20g yellow mustard@Pantry","120g devon@Deli","80g American-style cheese@Dairy","30g butter@Dairy"]},{"n":"Gun range nachos","note":"Baked corn chips with beans, cheddar, jalapeños, sour cream and salsa.","how":"Layer 150g corn chips with 150g refried beans, 80g grated cheddar and 30g drained sliced jalapeños in a shallow ovenproof dish. Bake at 200°C conventional for 8 minutes until the cheese melts and the beans are hot. Top with 80g sour cream and 100g tomato salsa. Serve immediately.","shop":["150g corn chips@Pantry","150g refried beans@Pantry","80g cheddar@Dairy","30g sliced jalapeños@Pantry","80g sour cream@Dairy","100g tomato salsa@Pantry"]}],"m":[{"n":"Tango's tailored rib eye","note":"Dry brined steak basted with butter, thyme and garlic.","how":"Pat dry four 200g rib eye steaks, season with 1 tsp fine salt and refrigerate uncovered for 4 to 12 hours to dry-brine. Heat a heavy pan with 1 tbsp neutral oil until hot. Sear the steaks hard for about 3 minutes per side in batches. Lower the heat and add 50g butter, 4 thyme sprigs and 3 crushed garlic cloves. Baste for 1 to 2 minutes. Remove at 54°C in the centre for medium rare, or cook longer if preferred. Rest for 8 minutes, slice and spoon over the pan butter.","shop":["800g rib eye steak@Meat","1 tsp fine salt@Pantry","1 tbsp neutral oil@Pantry","50g butter@Dairy","4 thyme sprigs@Produce","3 garlic cloves@Produce"]}],"w":[{"n":"Kiki's cupcakes","note":"Vanilla cupcakes with pink buttercream and a generous coat of sprinkles.","how":"Beat 80g softened butter with 80g caster sugar until pale. Beat in 1 egg and 1 tsp vanilla extract. Fold in 100g self-raising flour and 40ml milk. Divide between 8 cupcake cases and bake at 180°C conventional for 18 minutes until a skewer comes out clean. Cool completely. Beat 60g softened butter with 120g icing sugar and 1 tsp milk until fluffy; tint with a little pink food colouring. Pipe onto the cupcakes and cover with 20g sprinkles. Serve two small cupcakes each.","shop":["140g butter@Dairy","80g caster sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","100g self-raising flour@Pantry","45ml milk@Dairy","120g icing sugar@Pantry","pink food colouring@Pantry","20g sprinkles@Pantry"]}],"d":[{"n":"Breakout beer","note":"Cold lager served straight from the bottle for a celebratory clink.","how":"Chill four 375ml bottles of lager in the fridge for at least 2 hours. Open just before serving and clink the bottles carefully to celebrate the breakout.","shop":["4 x 375ml lager@Bottle shop"]}],"shopping":["8 slices white bread@Bakery","20g yellow mustard@Pantry","120g devon@Deli","80g American-style cheese@Dairy","220g butter@Dairy","150g corn chips@Pantry","150g refried beans@Pantry","80g cheddar@Dairy","30g sliced jalapeños@Pantry","80g sour cream@Dairy","100g tomato salsa@Pantry","800g rib eye steak@Meat","1 tsp fine salt@Pantry","1 tbsp neutral oil@Pantry","4 thyme sprigs@Produce","3 garlic cloves@Produce","80g caster sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","100g self-raising flour@Pantry","45ml milk@Dairy","120g icing sugar@Pantry","pink food colouring@Pantry","20g sprinkles@Pantry","4 x 375ml lager@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Beverly Hills Cop (1984)":{"poster":"assets/menu-posters/beverly-hills-cop-1984.jpg","colour":"#b32021","servings":4,"tagline":"Detroit attitude. Beverly Hills prices.","cue":"Serve the bananas when Axel stuffs them up the cop car's exhaust.","menu":{"s":[{"n":"Banana in the tailpipe bread","note":"Buttery banana bread bites, sliced thick and toasted in butter.","how":"Mash 3 overripe bananas and mix with 120g melted butter, 150g brown sugar, 1 egg and 1 tsp vanilla extract. Fold in 200g self-raising flour and a pinch of salt. Spoon into a lined small loaf tin and bake at 170°C conventional for 55 minutes until a skewer comes out clean. Cool completely. Cut four thick slices, halve each into bites and toast in a frying pan with 20g butter for 2 minutes per side. Save the remaining loaf for another day.","shop":["3 overripe bananas@Produce","140g butter@Dairy","150g brown sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","200g self-raising flour@Pantry","salt@Pantry"]},{"n":"Detroit coney sliders","note":"Mini franks with loose beef chilli, mustard and raw onion.","how":"Brown 150g fine beef mince with half a finely diced onion in 1 tsp oil for 5 minutes. Stir in 1 tsp chilli powder, 1/2 tsp cumin and 150ml water. Simmer gently for 45 minutes, adding water if needed to keep a loose spoonable chilli. Heat 8 cocktail franks in a griddle pan for 5 minutes until piping hot. Fill 8 mini hot dog buns with the franks, chilli, 20g yellow mustard and the remaining half onion diced raw. Serve two sliders each.","shop":["150g beef mince@Meat","1 onion@Produce","1 tsp oil@Pantry","1 tsp chilli powder@Pantry","1/2 tsp cumin@Pantry","8 cocktail franks@Meat","8 mini hot dog buns@Bakery","20g yellow mustard@Pantry"]}],"m":[{"n":"Beverly Palm room service","note":"Sirloin sandwich with caramelised onion, Swiss, horseradish mayo and fries.","how":"Cut 600g potatoes into fries, toss with 1 tbsp oil and bake at 220°C conventional for 30 minutes, turning halfway. Slowly cook 2 sliced brown onions in 20g butter over medium-low heat for 20 minutes until caramelised. Mix 60g mayonnaise with 20g horseradish. Season 600g sirloin steak and sear hard in a hot pan with 1 tsp oil for about 3 minutes per side to your preferred doneness. Rest 8 minutes and slice thin. Toast 4 brioche rolls. Fill with steak, caramelised onions, 100g Swiss cheese and horseradish mayo. Serve fries alongside.","shop":["600g potatoes@Produce","oil@Pantry","2 brown onions@Produce","20g butter@Dairy","60g mayonnaise@Pantry","20g horseradish@Pantry","600g sirloin steak@Meat","salt and pepper@Pantry","4 brioche rolls@Bakery","100g Swiss cheese@Dairy"]}],"w":[{"n":"Banana split","note":"Three ice creams, hot fudge, pineapple, strawberry sauce, cream and nuts.","how":"Split 4 bananas lengthways between four dishes. Put one 50ml scoop each of vanilla, chocolate and strawberry ice cream into each dish. Gently melt 80g dark chocolate with 60ml thickened cream to make hot fudge. Softly whip another 100ml cream. Add 100g drained crushed pineapple, 80ml strawberry sauce, the hot fudge and whipped cream, dividing evenly. Finish with 30g chopped nuts and 4 cherries. Serve immediately.","shop":["4 bananas@Produce","200ml vanilla ice cream@Frozen","200ml chocolate ice cream@Frozen","200ml strawberry ice cream@Frozen","80g dark chocolate@Pantry","160ml thickened cream@Dairy","100g crushed pineapple@Pantry","80ml strawberry sauce@Pantry","30g chopped nuts@Pantry","4 cherries@Produce"]}],"d":[{"n":"Detroit lager","note":"Ice cold American lager with a squeeze of fresh lime.","how":"Chill four 375ml bottles of American lager for at least 2 hours. Cut 1 lime into four wedges, squeeze one wedge into each bottle and serve ice cold.","shop":["4 x 375ml American lager@Bottle shop","1 lime@Produce"]}],"shopping":["7 bananas, 3 overripe@Produce","160g butter@Dairy","150g brown sugar@Pantry","1 egg@Dairy","1 tsp vanilla extract@Pantry","200g self-raising flour@Pantry","salt and pepper@Pantry","150g beef mince@Meat","3 onions@Produce","neutral oil@Pantry","1 tsp chilli powder@Pantry","1/2 tsp cumin@Pantry","8 cocktail franks@Meat","8 mini hot dog buns@Bakery","20g yellow mustard@Pantry","600g potatoes@Produce","60g mayonnaise@Pantry","20g horseradish@Pantry","600g sirloin steak@Meat","4 brioche rolls@Bakery","100g Swiss cheese@Dairy","200ml vanilla ice cream@Frozen","200ml chocolate ice cream@Frozen","200ml strawberry ice cream@Frozen","80g dark chocolate@Pantry","160ml thickened cream@Dairy","100g crushed pineapple@Pantry","80ml strawberry sauce@Pantry","30g chopped nuts@Pantry","4 cherries@Produce","4 x 375ml American lager@Bottle shop","1 lime@Produce"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Serendipity (2001)":{"poster":"assets/menu-posters/serendipity-2001.jpg","colour":"#842b3d","servings":4,"tagline":"Frozen hot chocolate. Fate decides.","cue":"Serve dessert when they first sit down at the dessert cafe.","menu":{"s":[{"n":"Christmas shopping pretzels","note":"Warm buttered pretzels, half salted and half coated in cinnamon sugar.","how":"Brush 4 small soft pretzels with 25g melted butter. Sprinkle two with 1/2 tsp coarse salt and two with a mixture of 15g caster sugar and 1/2 tsp cinnamon. Warm on a tray at 200°C conventional for 5 minutes. Cut each in half so everyone can taste both flavours.","shop":["4 small soft pretzels@Bakery","25g butter@Dairy","1/2 tsp coarse salt@Pantry","15g caster sugar@Pantry","1/2 tsp cinnamon@Pantry"]},{"n":"Wollman Rink roasted chestnuts","note":"Warm roasted chestnuts peeled from their curled shells with flaky salt.","how":"Score a cross through the shell of each of 400g chestnuts. Soak in water for 20 minutes and drain. Roast on a tray at 220°C conventional for 20 minutes until the shells curl back. Wrap in a clean towel for 5 minutes, then peel while still warm. Sprinkle with 1/4 tsp sea salt flakes and serve.","shop":["400g chestnuts@Produce","1/4 tsp sea salt flakes@Pantry"]}],"m":[{"n":"Manhattan bistro steak","note":"Butter basted sirloin, creamy brandy peppercorn sauce and double fried frites.","how":"Cut 800g potatoes into thin frites, rinse and dry thoroughly. Fry in neutral oil at 140°C for 5 minutes, drain and cool 15 minutes, then fry again at 185°C for 3 minutes until crisp. Season with salt. Season four 200g sirloin steaks and sear in a heavy hot pan with 1 tbsp neutral oil for about 3 minutes each side. Lower the heat, add 40g butter and 4 thyme sprigs, baste for 1 minute, then rest the steaks 8 minutes. Add 1 tsp cracked black peppercorns to the pan. Carefully add 40ml brandy away from the flame and simmer 1 minute. Add 150ml beef stock, reduce 5 minutes, stir in 100ml thickened cream and simmer 3 minutes. Serve with steaks and frites.","shop":["800g potatoes@Produce","neutral oil for frying and searing@Pantry","salt@Pantry","800g sirloin steak@Meat","40g butter@Dairy","4 thyme sprigs@Produce","1 tsp black peppercorns@Pantry","40ml brandy@Bottle shop","150ml beef stock@Pantry","100ml thickened cream@Dairy"]}],"w":[{"n":"Frozen hot chocolate","note":"Chocolate milk blended with ice, whipped cream and shaved chocolate.","how":"Gently melt 100g dark chocolate with 2 tbsp cocoa powder, 2 tbsp caster sugar and 100ml full cream milk, stirring until smooth. Cool completely. Blend with another 250ml full cream milk and 3 cups of ice, about 450g, until slushy. Divide into four small glasses. Softly whip 100ml thickened cream, spoon on top and finish with 20g shaved dark chocolate.","shop":["120g dark chocolate@Pantry","2 tbsp cocoa powder@Pantry","2 tbsp caster sugar@Pantry","350ml full cream milk@Dairy","450g ice@Frozen","100ml thickened cream@Dairy"]}],"d":[{"n":"Hot chocolate","note":"Frothy dark chocolate milk with a pinch of salt and marshmallows.","how":"Heat 600ml full cream milk over medium heat until steaming, about 4 minutes, without boiling. Add 100g chopped dark chocolate and a pinch of salt. Whisk until melted and frothy. Divide among four small mugs and top with 40g marshmallows.","shop":["600ml full cream milk@Dairy","100g dark chocolate@Pantry","salt@Pantry","40g marshmallows@Pantry"]}],"shopping":["4 small soft pretzels@Bakery","65g butter@Dairy","coarse and fine salt@Pantry","40g caster sugar@Pantry","1/2 tsp cinnamon@Pantry","400g chestnuts@Produce","1/4 tsp sea salt flakes@Pantry","800g potatoes@Produce","neutral oil for frying and searing@Pantry","800g sirloin steak@Meat","4 thyme sprigs@Produce","1 tsp black peppercorns@Pantry","40ml brandy@Bottle shop","150ml beef stock@Pantry","200ml thickened cream@Dairy","220g dark chocolate@Pantry","2 tbsp cocoa powder@Pantry","950ml full cream milk@Dairy","450g ice@Frozen","40g marshmallows@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Newsies (1992)":{"poster":"assets/menu-posters/newsies-1992.jpg","colour":"#912523","servings":4,"tagline":"Extra, extra, eat all about it.","cue":"Serve the mains when the strike starts.","menu":{"s":[{"n":"Hot pretzels","note":"Golden soft pretzels with a crisp crust and coarse salt.","how":"Mix 250g bread flour, 4g dried yeast, 1 tsp sugar, 1/2 tsp fine salt and 160ml warm water. Knead 8 minutes and rise covered for 1 hour. Shape into four small pretzels. Bring 1 litre water with 30g bicarbonate of soda to a simmer and bathe each pretzel for 30 seconds. Drain onto a lined tray, sprinkle with 1 tsp coarse salt and bake at 220°C conventional for 12 minutes until deep golden.","shop":["250g bread flour@Pantry","4g dried yeast@Pantry","1 tsp sugar@Pantry","fine salt@Pantry","30g bicarbonate of soda@Pantry","1 tsp coarse salt@Pantry"]},{"n":"Street corn on the cob","note":"Boiled then charred corn rolled in butter and flaky salt.","how":"Boil 4 small corn cobs in water for 5 minutes. Drain, then char on a hot grill for 5 to 7 minutes, turning often. Roll in 30g softened butter and sprinkle with 1/2 tsp sea salt flakes. Serve one cob each.","shop":["4 small corn cobs@Produce","30g butter@Dairy","1/2 tsp sea salt flakes@Pantry"]}],"m":[{"n":"Brooklyn hot dogs","note":"Blistered franks in steamed buns with mustard and tangy sauerkraut.","how":"Griddle 8 hot dog franks over medium-high heat for 6 to 8 minutes until blistered and piping hot. Steam 8 soft hot dog buns for 1 to 2 minutes until warm. Fill each bun with a frank, 1 tsp yellow mustard and a spoonful from 200g drained sauerkraut. Wrap in food-safe newspaper-style paper or baking paper. Serve two each.","shop":["8 hot dog franks@Meat","8 hot dog buns@Bakery","40g yellow mustard@Pantry","200g sauerkraut@Pantry"]}],"w":[{"n":"Apple turnovers","note":"Golden puff pastry parcels filled with buttery cinnamon apples.","how":"Peel, core and dice 400g apples. Cook with 20g butter, 40g caster sugar and 1/2 tsp cinnamon over medium heat for 10 minutes until tender and fairly dry. Cool. Cut 2 sheets puff pastry into four squares each. Divide filling among the squares, fold diagonally and seal the edges. Brush with 1 beaten egg. Bake at 200°C conventional for 20 minutes until golden. Serve two small turnovers each.","shop":["400g apples@Produce","20g butter@Dairy","40g caster sugar@Pantry","1/2 tsp cinnamon@Pantry","2 sheets puff pastry@Frozen","1 egg@Dairy"]}],"d":[{"n":"Root beer","note":"Ice cold root beer with a scoop of vanilla ice cream.","how":"Divide 400g ice among four tin mugs. Pour 250ml cold root beer into each, leaving space at the top. Add a 50ml scoop of vanilla ice cream to each mug and serve immediately with spoons.","shop":["400g ice@Frozen","1 litre root beer@Drinks","200ml vanilla ice cream@Frozen"]}],"shopping":["250g bread flour@Pantry","4g dried yeast@Pantry","45g caster sugar@Pantry","fine salt@Pantry","30g bicarbonate of soda@Pantry","1 tsp coarse salt@Pantry","4 small corn cobs@Produce","50g butter@Dairy","1/2 tsp sea salt flakes@Pantry","8 hot dog franks@Meat","8 hot dog buns@Bakery","40g yellow mustard@Pantry","200g sauerkraut@Pantry","400g apples@Produce","1/2 tsp cinnamon@Pantry","2 sheets puff pastry@Frozen","1 egg@Dairy","400g ice@Frozen","1 litre root beer@Drinks","200ml vanilla ice cream@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"You've Got Mail (1998)":{"poster":"assets/menu-posters/youve-got-mail-1998.jpg","colour":"#29523a","servings":4,"tagline":"Bouquets of sharpened pencils. Plates of cheese.","cue":"Serve the snacks when Joe sits down at Kathleen's cafe table.","menu":{"s":[{"n":"Cafe cheesecake bites","note":"Chilled baked cheesecake squares on biscuit bases, each topped with a cherry.","how":"Make one shared cheesecake slab for the bites and dessert. Line a 20cm square slice tin. Crush 180g digestive biscuits, mix with 75g melted butter and press into the base. Beat 600g cream cheese with 140g caster sugar until smooth. Beat in 150g sour cream, 3 eggs and 1 tsp vanilla extract. Pour over the base and bake at 150°C conventional for 50 to 60 minutes until the edges are set and the centre gently wobbles. Cool in the switched-off oven for 1 hour, then chill overnight. Cut a quarter of the slab into 8 small squares and top each with one of 8 pitted cherries. Reserve the remaining three quarters for Cafe cheesecake.","shop":["180g digestive biscuits, shared with dessert@Pantry","75g butter, shared with dessert@Dairy","600g cream cheese, shared with dessert@Dairy","140g caster sugar, shared with dessert@Pantry","150g sour cream, shared with dessert@Dairy","3 eggs, shared with dessert@Dairy","1 tsp vanilla extract, shared with dessert@Pantry","8 cherries@Produce"]},{"n":"Upper West Side bagels","note":"Toasted mini bagels with spring onion cream cheese and cracked pepper.","how":"Halve and toast 4 mini bagels until golden, about 3 minutes under a medium grill. Whip 120g cream cheese with 2 finely sliced spring onions and 1/4 tsp cracked black pepper. Spread over the eight toasted halves and serve two halves per person.","shop":["4 mini bagels@Bakery","120g cream cheese@Dairy","2 spring onions@Produce","black pepper@Pantry"]}],"m":[{"n":"Fox Books cafe sandwiches","note":"Pressed sourdough with turkey, melting brie and cranberry sauce.","how":"Spread 8 slices sourdough with 60g cranberry sauce. Divide 300g sliced cooked turkey and 160g brie among four slices and close the sandwiches. Butter the outsides using 30g softened butter. Press in a hot sandwich pan or frying pan weighted with a second pan for 3 to 4 minutes per side, until golden, the turkey is piping hot and the brie melts. Cut each sandwich in half.","shop":["8 slices sourdough@Bakery","60g cranberry sauce@Pantry","300g sliced cooked turkey@Deli","160g brie@Dairy","30g butter@Dairy"]}],"w":[{"n":"Cafe cheesecake","note":"Baked cheesecake with fresh strawberries macerated in a little sugar.","how":"Use the remaining three quarters of the baked cheesecake slab prepared and chilled overnight for Cafe cheesecake bites. The shared slab uses 180g digestive biscuits, 75g butter, 600g cream cheese, 140g caster sugar, 150g sour cream, 3 eggs and 1 tsp vanilla extract; make it once only. Slice 250g fresh strawberries and toss with 15g caster sugar. Leave for 20 minutes to macerate. Cut the reserved cheesecake into four dessert slices and serve with the strawberries and their juices.","shop":["shared cheesecake slab, ingredients listed with snack@Dairy","250g strawberries@Produce","15g caster sugar@Pantry"]}],"d":[{"n":"Tall decaf cappuccino","note":"Double decaf espresso with steamed milk and a deep foam cap.","how":"Use 72g decaf coffee beans to brew four double espressos, 60ml each, into warmed tall cups. Steam 600ml full cream milk in batches to 60°C, introducing enough air for a deep foam cap. Divide the steamed milk among the cups and spoon the foam on top. Serve immediately.","shop":["72g decaf coffee beans@Pantry","600ml full cream milk@Dairy"]}],"shopping":["180g digestive biscuits@Pantry","105g butter@Dairy","720g cream cheese@Dairy","155g caster sugar@Pantry","150g sour cream@Dairy","3 eggs@Dairy","1 tsp vanilla extract@Pantry","8 cherries@Produce","4 mini bagels@Bakery","2 spring onions@Produce","black pepper@Pantry","8 slices sourdough@Bakery","60g cranberry sauce@Pantry","300g sliced cooked turkey@Deli","160g brie@Dairy","250g strawberries@Produce","72g decaf coffee beans@Pantry","600ml full cream milk@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"When Harry Met Sally... (1989)":{"poster":"assets/menu-posters/when-harry-met-sally-1989.jpg","colour":"#8f202c","servings":4,"tagline":"Order whatever she's having.","cue":"Serve mains when they get to Katz's Deli.","menu":{"s":[{"n":"Potato knish","note":"Buttery potato and slow fried onion wrapped in golden puff pastry.","how":"Peel and chop 400g potatoes, boil in salted water for 15 minutes until tender, drain and mash. Slowly fry 1 finely diced brown onion in 30g butter over medium-low heat for 15 minutes until golden. Mix into the mash with 1/4 tsp salt and 1/4 tsp white pepper. Cool. Cut 2 sheets puff pastry into four squares each. Divide the filling among them, fold and seal into parcels. Brush with 1 beaten egg. Bake at 200°C conventional for 25 minutes until golden. Serve two small knish each with 40g hot English mustard.","shop":["400g potatoes@Produce","1 brown onion@Produce","30g butter@Dairy","salt@Pantry","1/4 tsp white pepper@Pantry","2 sheets puff pastry@Frozen","1 egg@Dairy","40g hot English mustard@Pantry"]},{"n":"Road trip grapes","note":"Chilled seeded grapes in small bunches, with a bowl for seeds.","how":"Rinse 400g seeded grapes, drain and snip into four small bunches. Refrigerate for 1 hour, then arrange on a dish over 300g ice just before serving. Put a small bowl beside the grapes for the seeds.","shop":["400g seeded grapes@Produce","300g ice@Frozen"]}],"m":[{"n":"Pastrami on rye","note":"Steamed pastrami piled on seeded rye with mustard and sour pickles.","how":"Place 600g sliced pastrami in a steamer over gently boiling water and steam for 10 minutes until glossy, soft and piping hot. Spread 8 slices seeded rye bread with 40g yellow mustard. Divide the pastrami between four slices, pile high and close the sandwiches. Serve each with 1 full sour dill pickle on the side.","shop":["600g sliced pastrami@Deli","8 slices seeded rye bread@Bakery","40g yellow mustard@Pantry","4 full sour dill pickles@Pantry"]}],"w":[{"n":"Apple pie à la mode, her way","note":"Warm apple pie with strawberry ice cream served on the side.","how":"Cut four slices from a 600g ready-baked apple pie. Warm on a tray at 180°C conventional for 10 minutes. Serve 75ml strawberry ice cream in a separate small bowl beside each slice. If strawberry ice cream is unavailable, softly whip 150ml thickened cream and serve it on the side instead.","shop":["600g ready-baked apple pie@Bakery","300ml strawberry ice cream or 150ml thickened cream@Frozen"]}],"d":[{"n":"Egg cream","note":"Chocolate syrup, cold milk and soda water stirred to a foamy head.","how":"Put 25ml chocolate syrup in each of four tall glasses. Pour 100ml very cold full cream milk into each. Add 150ml chilled soda water quickly and stir briskly to form a foamy head. Serve immediately. This drink contains no egg or cream.","shop":["100ml chocolate syrup@Drinks","400ml full cream milk@Dairy","600ml soda water@Drinks"]}],"shopping":["400g potatoes@Produce","1 brown onion@Produce","30g butter@Dairy","salt@Pantry","1/4 tsp white pepper@Pantry","2 sheets puff pastry@Frozen","1 egg@Dairy","40g hot English mustard@Pantry","400g seeded grapes@Produce","300g ice@Frozen","600g sliced pastrami@Deli","8 slices seeded rye bread@Bakery","40g yellow mustard@Pantry","4 full sour dill pickles@Pantry","600g ready-baked apple pie@Bakery","300ml strawberry ice cream@Frozen","150ml thickened cream, only if replacing ice cream@Dairy","100ml chocolate syrup@Drinks","400ml full cream milk@Dairy","600ml soda water@Drinks"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Secret of My Success (1987)":{"poster":"assets/menu-posters/the-secret-of-my-success-1987.jpg","colour":"#236164","servings":4,"tagline":"Mailroom by day. Executive by night.","cue":"Serve the mains when Brantley changes from mailroom clothes to his suit in the lift.","menu":{"s":[{"n":"Mailroom sandwich bites","note":"Ham, cheddar and pickle fingers on buttered white bread.","how":"Butter 8 slices of white bread with 30g softened butter. Layer 120g leg ham, 80g cheddar and 50g thinly sliced pickles across four slices. Top with the other slices, trim off the crusts and cut each sandwich into three fingers. Wrap in wax paper and refrigerate until serving.","shop":["8 slices white bread@Bakery","30g butter@Dairy","120g leg ham@Deli","80g cheddar@Dairy","50g pickles@Pantry"]},{"n":"Kansas corn fritters","note":"Golden corn fritters with spring onion and sour cream dip.","how":"Cut the kernels from 2 corn cobs, about 200g. Whisk 80g plain flour, 1 tsp baking powder, 1 egg and 60ml milk into a thick batter. Stir in the corn, 2 thinly sliced spring onions and 1/4 tsp salt. Heat 3 tbsp neutral oil in a frying pan over medium heat. Shallow-fry 8 spoonfuls of batter in batches for 3 minutes per side until golden and cooked through. Drain and serve with 100g sour cream for dipping.","shop":["2 corn cobs@Produce","80g plain flour@Pantry","1 tsp baking powder@Pantry","1 egg@Dairy","60ml milk@Dairy","2 spring onions@Produce","salt@Pantry","3 tbsp neutral oil@Pantry","100g sour cream@Dairy"]}],"m":[{"n":"Executive rib eye","note":"Dry brined steak basted with butter, thyme and garlic.","how":"Pat dry four 200g rib eye steaks. Sprinkle evenly with 1 tsp fine salt and refrigerate uncovered for 4 to 12 hours to dry-brine. Heat a heavy pan over high heat with 1 tbsp neutral oil. Sear the steaks for about 3 minutes per side, cooking in batches. Lower the heat, add 50g butter, 4 thyme sprigs and 3 lightly crushed garlic cloves. Baste repeatedly for 1 to 2 minutes. For medium rare, remove at 54°C in the centre; cook longer if preferred. Rest 8 minutes, then slice and spoon over the pan butter.","shop":["800g rib eye steak@Meat","1 tsp fine salt@Pantry","1 tbsp neutral oil@Pantry","50g butter@Dairy","4 thyme sprigs@Produce","3 garlic cloves@Produce"]}],"w":[{"n":"Kansas apple pie","note":"Golden double crust apple pie with cinnamon and vanilla ice cream.","how":"Line a 20cm pie dish with half of 400g sweet shortcrust pastry. Peel, core and slice 600g Granny Smith apples, then toss with 80g caster sugar and 1 tsp cinnamon. Fill the crust, cover with the remaining pastry and crimp. Cut steam vents, brush with 1 beaten egg and sprinkle with 1 tsp extra sugar. Bake at 190°C conventional for 50 minutes until golden and tender. Rest 20 minutes, divide into four portions and serve with 200ml vanilla ice cream.","shop":["400g sweet shortcrust pastry@Frozen","600g Granny Smith apples@Produce","85g caster sugar@Pantry","1 tsp cinnamon@Pantry","1 egg@Dairy","200ml vanilla ice cream@Frozen"]}],"d":[{"n":"Martini","note":"Gin and dry vermouth stirred over ice with a lemon twist.","how":"Freeze four martini glasses for 15 minutes. Working in two batches, stir a total of 240ml gin and 40ml dry vermouth with 400g ice for 30 seconds per batch. Strain equally into the frozen glasses. Cut four thin twists from 1 lemon, express their oils over the drinks and garnish each with a twist.","shop":["240ml gin@Bottle shop","40ml dry vermouth@Bottle shop","400g ice@Frozen","1 lemon@Produce"]}],"shopping":["8 slices white bread@Bakery","80g butter@Dairy","120g leg ham@Deli","80g cheddar@Dairy","50g pickles@Pantry","2 corn cobs@Produce","80g plain flour@Pantry","1 tsp baking powder@Pantry","2 eggs@Dairy","60ml milk@Dairy","2 spring onions@Produce","fine salt@Pantry","4 tbsp neutral oil@Pantry","100g sour cream@Dairy","800g rib eye steak@Meat","4 thyme sprigs@Produce","3 garlic cloves@Produce","400g sweet shortcrust pastry@Frozen","600g Granny Smith apples@Produce","85g caster sugar@Pantry","1 tsp cinnamon@Pantry","200ml vanilla ice cream@Frozen","240ml gin@Bottle shop","40ml dry vermouth@Bottle shop","400g ice@Frozen","1 lemon@Produce"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Adjustment Bureau (2011)":{"poster":"assets/menu-posters/the-adjustment-bureau-2011.jpg","colour":"#8d4e2e","servings":4,"tagline":"Fate has a plan. So does dessert.","cue":"Serve the snacks when David meets Elise on the bus.","menu":{"s":[{"n":"Bus ride pretzels","note":"Warm soft pretzels with everything seasoning and cream cheese dip.","how":"Brush 4 small soft pretzels with 20g melted butter, sprinkle with 2 tsp everything bagel seasoning and warm on a tray at 200°C conventional for 5 minutes. Divide 100g cream cheese into a small dipping bowl and serve alongside.","shop":["4 small soft pretzels@Bakery","20g butter@Dairy","2 tsp everything bagel seasoning@Pantry","100g cream cheese@Dairy"]},{"n":"Rooftop crostini","note":"Toasted baguette with whipped goat's cheese, warm honey and thyme.","how":"Cut half a baguette, about 150g, into 8 slices. Toast at 200°C conventional for 5 to 7 minutes until golden. Beat 120g soft goat's cheese with 30ml thickened cream until light. Warm 30g honey gently for 30 seconds. Spread the cheese on the toast, drizzle with warm honey and finish with 1 tsp thyme leaves and 1/4 tsp cracked black pepper.","shop":["150g baguette@Bakery","120g soft goat's cheese@Dairy","30ml thickened cream@Dairy","30g honey@Pantry","1 tsp thyme leaves@Produce","black pepper@Pantry"]}],"m":[{"n":"Manhattan steak frites","note":"Seared sirloin, shallot red wine butter and double fried frites.","how":"Finely dice 2 shallots and simmer with 80ml red wine in a small pan for 8 minutes until almost dry. Cool, then mix into 60g softened butter with a pinch of salt. Chill. Cut 800g potatoes into frites, rinse and dry thoroughly. Fry in neutral oil at 140°C for 5 minutes, drain and cool 15 minutes; fry again at 185°C for 3 minutes until crisp. Salt lightly. Season four 200g sirloin steaks, sear hard in a hot pan with 1 tbsp oil for about 3 minutes each side to your preferred doneness, then rest 8 minutes. Slice and top with the shallot red wine butter; serve with frites.","shop":["2 shallots@Produce","80ml red wine@Bottle shop","60g butter@Dairy","salt@Pantry","800g potatoes@Produce","neutral oil for frying and searing@Pantry","800g sirloin steak@Meat"]}],"w":[{"n":"Chocolate fondant","note":"Warm dark chocolate cakes with soft melting centres.","how":"Butter four 150ml moulds using 10g extra butter. Heat the oven to 200°C conventional. Melt 125g dark chocolate with 125g butter gently and cool slightly. Whisk 2 whole eggs and 2 yolks with 60g caster sugar until pale. Stir in the chocolate mixture, then fold in 30g plain flour. Divide among the moulds and bake for 10 minutes until the edges are set and centres remain soft. Rest 1 minute, loosen the edges and carefully turn onto plates. Serve immediately.","shop":["125g dark chocolate@Pantry","135g butter@Dairy","4 eggs, 2 whole and 2 yolks@Dairy","60g caster sugar@Pantry","30g plain flour@Pantry"]}],"d":[{"n":"Champagne","note":"Brut champagne chilled and poured into tall sparkling flutes.","how":"Chill one 750ml bottle of brut champagne to about 7°C in the fridge. Pour 125ml into each of four flutes and keep the remainder chilled with a sparkling-wine stopper.","shop":["750ml brut champagne@Bottle shop"]}],"shopping":["4 small soft pretzels@Bakery","215g butter@Dairy","2 tsp everything bagel seasoning@Pantry","100g cream cheese@Dairy","150g baguette@Bakery","120g soft goat's cheese@Dairy","30ml thickened cream@Dairy","30g honey@Pantry","1 tsp thyme leaves@Produce","black pepper@Pantry","2 shallots@Produce","80ml red wine@Bottle shop","salt@Pantry","800g potatoes@Produce","neutral oil for frying and searing@Pantry","800g sirloin steak@Meat","125g dark chocolate@Pantry","4 eggs@Dairy","60g caster sugar@Pantry","30g plain flour@Pantry","750ml brut champagne@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Frequency (2000)":{"poster":"assets/menu-posters/frequency-2000.jpg","colour":"#225444","servings":4,"tagline":"Father and son. Same radio. Same pizza.","cue":"Serve dinner during the 1969 World Series broadcast.","menu":{"s":[{"n":"Firehouse chilli bites","note":"Beef and bean chilli in baked wonton cups with melted cheddar.","how":"Press 12 wonton wrappers into a lightly oiled mini muffin tin. Bake at 180°C conventional for 7 minutes until crisp. Brown 200g beef mince in 1 tsp oil for 5 minutes, add 1/2 diced onion and cook 3 minutes. Stir in 1 tsp chilli powder, 200g chopped tinned tomatoes and 120g drained kidney beans. Simmer 15 minutes until thick. Spoon into the baked cups, top with 60g grated cheddar and return to the oven for 3 minutes to melt. Serve three cups each.","shop":["12 wonton wrappers@Pantry","neutral oil@Pantry","200g beef mince@Meat","1/2 onion@Produce","1 tsp chilli powder@Pantry","200g tinned tomatoes@Pantry","120g drained kidney beans@Pantry","60g cheddar@Dairy"]},{"n":"Ballpark peanuts","note":"Warm roasted peanuts in their shells, tossed with fine salt.","how":"Spread 200g peanuts in their shells on a baking tray. Roast at 180°C conventional for 20 minutes, shaking the tray halfway. Toss while hot with 1/2 tsp fine salt. Cool slightly and divide into four bowls, with an empty bowl for the shells.","shop":["200g peanuts in the shell@Pantry","1/2 tsp fine salt@Pantry"]}],"m":[{"n":"Queens pizza","note":"Thin crisp pizza with crushed tomato, mozzarella and crumbled Italian sausage.","how":"Mix 380g bread flour, 2g dried yeast, 1 tsp salt and 245ml cool water; knead 8 minutes. Divide into two balls and refrigerate covered for 24 to 48 hours to cold-ferment. Bring to room temperature for 2 hours. Heat a pizza steel at the oven's maximum temperature, about 250 to 275°C, for 45 minutes. Remove 200g Italian sausages from their casings and crumble; pan-fry 5 minutes until cooked. Stretch the dough thin into two pizzas. Top with 200g crushed tomatoes, 200g low-moisture mozzarella and the sausage, dividing evenly. Bake each on the steel for about 7 minutes until crisp and cooked. Cut into wedges for four people.","shop":["380g bread flour@Pantry","2g dried yeast@Pantry","1 tsp salt@Pantry","200g Italian sausages@Meat","200g crushed tomatoes@Pantry","200g low-moisture mozzarella@Dairy"]}],"w":[{"n":"Julia's apple pie","note":"Double crust apple pie with cinnamon, sugar and golden egg wash.","how":"Line a 20cm pie dish with half of 400g sweet shortcrust pastry. Peel, core and thinly slice 600g Granny Smith apples. Toss with 80g caster sugar, 1 tsp cinnamon and 15g plain flour. Fill the pastry, cover with the remaining pastry and crimp the edges. Cut two steam vents, brush with 1 beaten egg and sprinkle with 1 tsp extra sugar. Bake at 190°C conventional for 50 minutes until golden and the apples are tender. Rest 20 minutes and cut into four portions.","shop":["400g sweet shortcrust pastry@Frozen","600g Granny Smith apples@Produce","85g caster sugar@Pantry","1 tsp cinnamon@Pantry","15g plain flour@Pantry","1 egg@Dairy"]}],"d":[{"n":"Cooler beer","note":"American lager chilled in an ice-filled esky before the game.","how":"Bury four 375ml cans of American lager in an esky filled with 2kg ice for 1 hour before the first pitch. Open just before serving, one can per person.","shop":["4 x 375ml American lager@Bottle shop","2kg ice@Frozen"]}],"shopping":["12 wonton wrappers@Pantry","neutral oil@Pantry","200g beef mince@Meat","1 small onion, use half@Produce","1 tsp chilli powder@Pantry","400g crushed or chopped tinned tomatoes@Pantry","120g drained kidney beans@Pantry","60g cheddar@Dairy","200g peanuts in the shell@Pantry","fine salt@Pantry","380g bread flour@Pantry","2g dried yeast@Pantry","200g Italian sausages@Meat","200g low-moisture mozzarella@Dairy","400g sweet shortcrust pastry@Frozen","600g Granny Smith apples@Produce","85g caster sugar@Pantry","1 tsp cinnamon@Pantry","15g plain flour@Pantry","1 egg@Dairy","4 x 375ml American lager@Bottle shop","2kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"After Hours (1985)":{"poster":"assets/menu-posters/after-hours-1985.jpg","colour":"#c04c19","servings":4,"tagline":"It's after midnight. Do you know where your dinner is?","cue":"Serve the bagels when Kiki shows off her bagel and cream cheese paperweights.","menu":{"s":[{"n":"Terminal Bar fries","note":"Double fried thin chips with salt and a little garlic powder.","how":"Cut 500g potatoes into thin fries, rinse and dry thoroughly. Heat vegetable oil in a sturdy deep pan to 140°C. Blanch the fries in batches for 5 minutes without browning; drain and cool for 15 minutes. Heat the oil to 185°C and fry again for 2 to 3 minutes until golden and crisp. Drain, then toss with 1/2 tsp salt and 1/4 tsp garlic powder.","shop":["500g potatoes@Produce","vegetable oil for frying@Pantry","1/2 tsp salt@Pantry","1/4 tsp garlic powder@Pantry"]},{"n":"Soft serve cones","note":"Piped vanilla ice cream in cones with crisp chocolate shell.","how":"Melt 80g dark chocolate with 20g coconut oil gently, stirring until smooth. Cool until just warm. Soften 300ml vanilla ice cream in the fridge for about 10 minutes, only until pipeable. Transfer to a piping bag with a large star nozzle and pipe into 4 small waffle cones. Dip the tops in the chocolate mixture; hold upright until the shell sets and serve immediately.","shop":["80g dark chocolate@Pantry","20g coconut oil@Pantry","300ml vanilla ice cream@Frozen","4 small waffle cones@Bakery"]}],"m":[{"n":"Terminal Bar burger","note":"Thick griddled chuck patty, cheddar, raw onion and pickles.","how":"Hand-form 600g beef chuck mince into four thick patties without overworking. Heat a griddle over medium-high heat. Season with 1/2 tsp salt and 1/4 tsp pepper just before cooking. Griddle for 5 to 6 minutes each side until cooked through, checking the centre reaches 75°C. Top with 80g cheddar in the last minute. Toast 4 burger buns cut-side down. Assemble with the patties, 1 thinly sliced raw onion and 80g sliced dill pickles.","shop":["600g beef chuck mince@Meat","salt@Pantry","black pepper@Pantry","80g cheddar@Dairy","4 burger buns@Bakery","1 onion@Produce","80g dill pickles@Pantry"]}],"w":[{"n":"White frosted plaster cake","note":"Vanilla butter cake with thick matte white seven-minute frosting.","how":"Heat the oven to 180°C conventional and line a 16cm cake tin. Beat 100g softened butter with 100g caster sugar until pale. Beat in 2 eggs and 1 tsp vanilla extract, then fold in 120g self-raising flour and 30ml milk. Bake for 30 to 35 minutes until a skewer comes out clean; cool completely. For seven-minute frosting, whisk 2 egg whites, 120g caster sugar and 1 tbsp water in a heatproof bowl over gently simmering water for 7 minutes, until thick, glossy and hot throughout. Remove from the heat and whisk 2 minutes more until stiff. Cover the cake in a thick matte-looking layer, roughly smoothing it like plaster. Cut into four pieces.","shop":["100g butter@Dairy","220g caster sugar@Pantry","4 eggs, 2 whole and 2 whites@Dairy","1 tsp vanilla extract@Pantry","120g self-raising flour@Pantry","30ml milk@Dairy"]}],"d":[{"n":"Last call beer","note":"American lager poured with a generous two-finger foam head.","how":"Chill four 568ml cans of American lager in the fridge for at least 2 hours. Pour each into a clean pint glass, tilting at first and straightening near the end to form a two-finger foam head.","shop":["4 x 568ml American lager@Bottle shop"]}],"shopping":["500g potatoes@Produce","vegetable oil for frying@Pantry","salt@Pantry","1/4 tsp garlic powder@Pantry","80g dark chocolate@Pantry","20g coconut oil@Pantry","300ml vanilla ice cream@Frozen","4 small waffle cones@Bakery","600g beef chuck mince@Meat","black pepper@Pantry","80g cheddar@Dairy","4 burger buns@Bakery","1 onion@Produce","80g dill pickles@Pantry","100g butter@Dairy","220g caster sugar@Pantry","4 eggs@Dairy","1 tsp vanilla extract@Pantry","120g self-raising flour@Pantry","30ml milk@Dairy","4 x 568ml American lager@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"King of New York (1990)":{"poster":"assets/menu-posters/king-of-new-york-1990.jpg","colour":"#16395c","servings":4,"tagline":"Uptown deals. Downtown appetite.","cue":"Serve the mains when Frank checks back into the Plaza.","menu":{"s":[{"n":"Chinatown dumplings","note":"Crisp pork and chive dumplings with black vinegar and chilli oil.","how":"Heat 1 tbsp neutral oil in a non-stick pan over medium-high heat. Add 12 frozen pork and chive dumplings and pan-fry for 3 minutes until their bottoms crisp. Add 80ml water and immediately cover. Steam for 7 to 9 minutes, or the packet time, until cooked through; remove the lid and let the water evaporate. Mix 2 tbsp black vinegar, 1 tbsp soy sauce and 1 tsp chilli oil for dipping.","shop":["12 frozen pork and chive dumplings@Frozen","1 tbsp neutral oil@Pantry","2 tbsp black vinegar@Pantry","1 tbsp soy sauce@Pantry","1 tsp chilli oil@Pantry"]},{"n":"Subway pretzels","note":"Warm soft pretzels with melted butter, coarse salt and yellow mustard.","how":"Brush 4 small soft pretzels with 25g melted butter and sprinkle with 1/2 tsp coarse salt. Warm on a tray at 200°C conventional for 5 minutes. Serve with 40g yellow mustard on the side.","shop":["4 small soft pretzels@Bakery","25g butter@Dairy","1/2 tsp coarse salt@Pantry","40g yellow mustard@Pantry"]}],"m":[{"n":"Frank's Plaza steak dinner","note":"Seared rib eye, creamy brandy peppercorn sauce and crisp frites.","how":"Cut 800g potatoes into thin frites, rinse and dry thoroughly. Fry in neutral oil at 140°C for 5 minutes, drain and cool, then fry at 185°C for 3 minutes until crisp. Season with salt. Pat dry four 200g rib eye steaks and season. Heat 1 tbsp neutral oil in a heavy pan, sear the steaks for about 3 minutes each side to your preferred doneness, then rest 8 minutes. For sauce, add 1 tsp cracked black peppercorns to the pan, then carefully add 40ml brandy away from the flame. Simmer 1 minute, add 150ml beef stock and reduce for 5 minutes. Add 100ml thickened cream and simmer 3 minutes. Serve steaks with sauce and frites.","shop":["800g potatoes@Produce","neutral oil for frying and searing@Pantry","salt@Pantry","800g rib eye steak@Meat","1 tsp black peppercorns@Pantry","40ml brandy@Bottle shop","150ml beef stock@Pantry","100ml thickened cream@Dairy"]}],"w":[{"n":"New York cheesecake","note":"Cream cheese and sour cream filling on a buttery biscuit base.","how":"Line a 16cm springform tin and wrap the outside tightly in two layers of foil. Crush 120g digestive biscuits, mix with 50g melted butter and press into the base. Beat 450g cream cheese with 100g caster sugar until smooth, then beat in 80g sour cream, 2 eggs and zest of 1 lemon. Pour into the tin. Put the tin in a roasting pan and add hot water halfway up its sides. Bake at 150°C conventional for 70 minutes until the edges are set and the centre gently wobbles. Turn off the oven, leave the door ajar and cool inside for 1 hour. Refrigerate overnight. Cut into four generous slices.","shop":["120g digestive biscuits@Pantry","50g butter@Dairy","450g cream cheese@Dairy","100g caster sugar@Pantry","80g sour cream@Dairy","2 eggs@Dairy","1 lemon@Produce"]}],"d":[{"n":"Champagne","note":"Brut champagne chilled and poured into elegant shallow coupes.","how":"Chill one 750ml bottle of brut champagne to about 7°C in the fridge or an ice bucket. Pour 125ml into each of four coupes and keep the remainder cold with a sparkling-wine stopper.","shop":["750ml brut champagne@Bottle shop","ice@Frozen"]}],"shopping":["12 frozen pork and chive dumplings@Frozen","neutral oil for frying and searing@Pantry","2 tbsp black vinegar@Pantry","1 tbsp soy sauce@Pantry","1 tsp chilli oil@Pantry","4 small soft pretzels@Bakery","75g butter@Dairy","coarse and fine salt@Pantry","40g yellow mustard@Pantry","800g potatoes@Produce","800g rib eye steak@Meat","1 tsp black peppercorns@Pantry","40ml brandy@Bottle shop","150ml beef stock@Pantry","100ml thickened cream@Dairy","120g digestive biscuits@Pantry","450g cream cheese@Dairy","100g caster sugar@Pantry","80g sour cream@Dairy","2 eggs@Dairy","1 lemon@Produce","750ml brut champagne@Bottle shop","ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Spider-Man 2 (2004)":{"poster":"assets/menu-posters/spider-man-2-2004.jpg","colour":"#a11f26","servings":4,"tagline":"Thirty minutes or it's free.","cue":"Order the pizza when Peter races across the city on a delivery.","menu":{"s":[{"n":"Joe's Pizza garlic knots","note":"Golden dough knots tossed in garlic butter and fresh parsley.","how":"Cut 300g pizza dough into 8 strips and tie into knots. Cover on a lined tray and prove 30 minutes. Bake at 230°C conventional for 12 minutes until golden. Melt 40g butter with 2 crushed garlic cloves over low heat for 2 minutes. Toss the hot knots in the garlic butter and 2 tbsp chopped parsley.","shop":["300g pizza dough@Bakery","40g butter@Dairy","2 garlic cloves@Produce","2 tbsp parsley@Produce"]},{"n":"Doc Ock's tentacle pretzels","note":"Long soft pretzel ropes with coarse salt and hot mustard.","how":"Mix 250g bread flour, 4g dried yeast, 1 tsp sugar, 1/2 tsp fine salt and 160ml warm water. Knead 8 minutes and rise covered for 1 hour. Divide into 8 portions and roll into long curling tentacle ropes. Bring 1 litre water and 30g bicarbonate of soda to a simmer. Dip each rope for 20 seconds, drain onto a lined tray and sprinkle with 1 tsp coarse salt. Bake at 220°C conventional for 12 to 15 minutes until deep golden. Serve with 40g hot mustard.","shop":["250g bread flour@Pantry","4g dried yeast@Pantry","1 tsp sugar@Pantry","fine salt@Pantry","30g bicarbonate of soda@Pantry","1 tsp coarse salt@Pantry","40g hot mustard@Pantry"]}],"m":[{"n":"Thirty-minute pepperoni pie","note":"Thin crisp pizza with crushed tomato, mozzarella and cupping pepperoni.","how":"Mix 380g bread flour, 2g dried yeast, 1 tsp salt and 245ml cool water. Knead 8 minutes, divide into 2 balls and refrigerate covered for 24 to 48 hours to cold-ferment. Bring to room temperature for 2 hours. Heat a pizza steel in the oven at its maximum temperature, about 250 to 275°C, for 45 minutes. Stretch each dough ball thin. Spread each with half of 200g crushed tomatoes and top with half of 200g low-moisture mozzarella and 100g thinly sliced cupping pepperoni. Bake one at a time on the hot steel for about 7 minutes, until the crust is cooked and crisp. Cut both pizzas into wedges for four people.","shop":["380g bread flour@Pantry","2g dried yeast@Pantry","1 tsp salt@Pantry","200g crushed tomatoes@Pantry","200g low-moisture mozzarella@Dairy","100g pepperoni@Deli"]}],"w":[{"n":"Aunt May's pancakes","note":"Fluffy buttermilk pancakes cooked in butter and stacked with maple syrup.","how":"Separate 2 eggs. Mix 150g plain flour, 1 tsp baking powder, 20g sugar and a pinch of salt. Whisk the yolks with 180ml buttermilk and fold into the flour. Whip the whites to soft peaks and gently fold through. Melt a little of 30g butter in a frying pan over medium heat. Cook eight small pancakes in batches, about 2 minutes until bubbles set, then flip and cook 1 minute. Stack two per person and serve with 80ml maple syrup.","shop":["2 eggs@Dairy","150g plain flour@Pantry","1 tsp baking powder@Pantry","20g sugar@Pantry","salt@Pantry","180ml buttermilk@Dairy","30g butter@Dairy","80ml maple syrup@Pantry"]}],"d":[{"n":"Iced coffee","note":"Cold brew with milk, ice and vanilla ice cream.","how":"Steep 80g coarsely ground coffee beans in 800ml cold water, covered in the fridge, for 12 to 18 hours. Strain through a coffee filter. Divide 400g ice between four glasses, add 150ml cold brew and 100ml full cream milk to each, then top each with 50ml vanilla ice cream. Refrigerate leftover cold brew.","shop":["80g coffee beans@Pantry","400g ice@Frozen","400ml full cream milk@Dairy","200ml vanilla ice cream@Frozen"]}],"shopping":["300g pizza dough@Bakery","70g butter@Dairy","2 garlic cloves@Produce","2 tbsp parsley@Produce","630g bread flour@Pantry","6g dried yeast@Pantry","25g sugar@Pantry","fine salt@Pantry","30g bicarbonate of soda@Pantry","1 tsp coarse salt@Pantry","40g hot mustard@Pantry","200g crushed tomatoes@Pantry","200g low-moisture mozzarella@Dairy","100g pepperoni@Deli","2 eggs@Dairy","150g plain flour@Pantry","1 tsp baking powder@Pantry","180ml buttermilk@Dairy","80ml maple syrup@Pantry","80g coffee beans@Pantry","400g ice@Frozen","400ml full cream milk@Dairy","200ml vanilla ice cream@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Prizzi's Honor (1985)":{"poster":"assets/menu-posters/prizzis-honor-1985.jpg","colour":"#6c2025","servings":4,"tagline":"Love, honour and a very complicated wedding.","cue":"Serve dessert at the wedding, when Charley first spots Irene.","menu":{"s":[{"n":"Prizzi wedding antipasto","note":"Lemon marinated mushrooms, salami, mixed olives and tender artichokes.","how":"Blanch 200g button mushrooms in boiling water for 1 minute and drain well. Toss with 2 tbsp olive oil, juice of half a lemon, 1 crushed garlic clove and 1 tbsp chopped parsley. Refrigerate covered overnight. Serve on a platter with 100g salami, 120g mixed olives and 150g drained marinated artichokes for four people.","shop":["200g button mushrooms@Produce","2 tbsp olive oil@Pantry","1/2 lemon@Produce","1 garlic clove@Produce","1 tbsp parsley@Produce","100g salami@Deli","120g mixed olives@Deli","150g marinated artichokes@Pantry"]},{"n":"Fried zucchini","note":"Crisp battered zucchini batons with salt and fresh lemon.","how":"Cut 2 medium zucchini, about 400g, into batons and pat dry. Toss with 30g plain flour. Whisk 100g plain flour with 150ml cold sparkling water to a light batter. Heat neutral oil in a deep sturdy pan to 185°C. Dip the batons in batter and fry in small batches for 3 minutes until crisp and golden. Drain, season with 1/4 tsp salt and serve with the remaining half lemon cut into wedges.","shop":["400g zucchini@Produce","130g plain flour@Pantry","150ml sparkling water@Drinks","neutral oil for frying@Pantry","salt@Pantry","1/2 lemon@Produce"]}],"m":[{"n":"Don Corrado's baked ziti","note":"Slow sausage sugo, seasoned ricotta and mozzarella, baked until blistered.","how":"Remove 400g Italian sausages from their casings. Brown in 1 tbsp olive oil for 8 minutes, breaking up the meat. Add 1 diced onion and cook 5 minutes, then 2 crushed garlic cloves for 1 minute. Add 700g passata, 150ml water and 1 tsp dried oregano. Simmer gently for 45 minutes, stirring. Boil 350g ziti or penne for 2 minutes less than the packet time. Mix 250g ricotta with 1/4 tsp each salt and pepper. Layer the pasta and sausage sugo with spoonfuls of ricotta in an ovenproof dish, scattering 200g mozzarella between layers and over the top. Bake at 200°C conventional for 25 minutes until piping hot and blistered; rest 10 minutes before serving.","shop":["400g Italian sausages@Meat","1 tbsp olive oil@Pantry","1 onion@Produce","2 garlic cloves@Produce","700g passata@Pantry","1 tsp dried oregano@Pantry","350g ziti or penne@Pantry","250g ricotta@Dairy","salt@Pantry","black pepper@Pantry","200g mozzarella@Dairy"]}],"w":[{"n":"Wedding almond cookies","note":"Crackled amaretti with almond meal, sugar and a snowy icing coat.","how":"Heat the oven to 170°C conventional. Whisk 2 egg whites to stiff peaks in a clean bowl. Gently fold in 250g almond meal, 200g caster sugar and 1/2 tsp almond extract. Shape into 20 small balls, roll in 40g icing sugar and space on lined trays. Bake 15 minutes until crackled and lightly golden. Cool on the trays for 10 minutes, then transfer to a rack. Serve five small cookies each, or save extras in an airtight tin.","shop":["2 eggs, whites only@Dairy","250g almond meal@Pantry","200g caster sugar@Pantry","1/2 tsp almond extract@Pantry","40g icing sugar@Pantry"]}],"d":[{"n":"Prosecco","note":"Chilled sparkling wine served in flutes for the wedding toast.","how":"Chill one 750ml bottle of prosecco in an ice bucket for 30 minutes until about 6°C. Pour 125ml into each of four flutes for the toast. Keep the remainder cold with a sparkling-wine stopper.","shop":["750ml prosecco@Bottle shop","ice@Frozen"]}],"shopping":["200g button mushrooms@Produce","3 tbsp olive oil@Pantry","1 lemon@Produce","3 garlic cloves@Produce","1 tbsp parsley@Produce","100g salami@Deli","120g mixed olives@Deli","150g marinated artichokes@Pantry","400g zucchini@Produce","130g plain flour@Pantry","150ml sparkling water@Drinks","neutral oil for frying@Pantry","salt@Pantry","black pepper@Pantry","400g Italian sausages@Meat","1 onion@Produce","700g passata@Pantry","1 tsp dried oregano@Pantry","350g ziti or penne@Pantry","250g ricotta@Dairy","200g mozzarella@Dairy","2 eggs@Dairy","250g almond meal@Pantry","200g caster sugar@Pantry","1/2 tsp almond extract@Pantry","40g icing sugar@Pantry","750ml prosecco@Bottle shop","ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"A Bronx Tale (1993)":{"poster":"assets/menu-posters/a-bronx-tale-1993.jpg","colour":"#6b201b","servings":4,"tagline":"The saddest thing in life is a wasted dinner.","cue":"Do the car door test before dessert comes out.","menu":{"s":[{"n":"Chez Bippy bar snacks","note":"Warm chilli peanuts, sharp provolone, marinated olives and lemon zest.","how":"Warm 150g salted peanuts in a dry pan over medium heat for 3 minutes, tossing often. Toss with 1/4 tsp chilli flakes. Cut 120g sharp provolone into cubes. Mix 150g drained marinated olives with half the finely grated zest of 1 lemon. Divide the peanuts, cheese and olives between small bar bowls for four people.","shop":["150g salted peanuts@Pantry","1/4 tsp chilli flakes@Pantry","120g sharp provolone@Deli","150g marinated olives@Deli","1 lemon@Produce"]},{"n":"Doo-wop garlic knots","note":"Fresh baked dough knots tossed in garlic butter, parsley and parmesan.","how":"Cut 400g pizza dough into 12 strips and tie each in a loose knot. Place on a lined tray, cover and prove in a warm place for 30 minutes. Bake at 230°C conventional for 12 minutes until golden. Melt 50g butter with 2 finely minced garlic cloves over low heat for 2 minutes. Toss the hot knots straight from the oven with the garlic butter, 2 tbsp chopped parsley and 30g finely grated parmesan.","shop":["400g pizza dough@Bakery","50g butter@Dairy","2 garlic cloves@Produce","2 tbsp parsley@Produce","30g parmesan@Dairy"]}],"m":[{"n":"Sonny's Sunday rigatoni","note":"Slow tomato sauce, pork and beef meatballs, tender ribs and basil.","how":"Mix 400g pork and beef mince with 1 egg, 40g breadcrumbs, 1/2 tsp salt and 1/4 tsp black pepper; shape into 12 meatballs. Brown the meatballs and 400g pork ribs in 2 tbsp olive oil in a heavy pot for 8 minutes, turning, then set aside. Soften 1 diced onion for 5 minutes, add 3 sliced garlic cloves for 1 minute, then add 800g tinned tomatoes, 200ml water and 10 basil leaves. Return the meat, cover partly and simmer gently for 2 hours, stirring occasionally and adding water if needed. Check the ribs are tender and the meatballs are cooked through. Boil 400g rigatoni in salted water for the packet time, drain and toss with sauce. Serve the meat on a platter with the pasta.","shop":["400g pork and beef mince@Meat","400g pork ribs@Meat","1 egg@Dairy","40g breadcrumbs@Pantry","salt@Pantry","black pepper@Pantry","2 tbsp olive oil@Pantry","1 onion@Produce","3 garlic cloves@Produce","800g tinned tomatoes@Pantry","10 basil leaves@Produce","400g rigatoni@Pantry"]}],"w":[{"n":"Arthur Avenue cannoli","note":"Crisp shells filled with vanilla ricotta, chocolate chips and crushed pistachio.","how":"Drain 250g fresh ricotta in a lined sieve in the fridge for at least 2 hours. Beat with 40g icing sugar and 1/2 tsp vanilla extract until smooth; fold in 30g mini chocolate chips. Pipe into 8 small bought cannoli shells just before serving. Dip the ends in 30g finely crushed pistachios. Serve two small cannoli per person.","shop":["250g fresh ricotta@Dairy","40g icing sugar@Pantry","1/2 tsp vanilla extract@Pantry","30g mini chocolate chips@Pantry","8 small cannoli shells@Bakery","30g pistachios@Pantry"]}],"d":[{"n":"Espresso with anisette","note":"Short espresso with anisette on the side and fresh lemon peel.","how":"Use 36g espresso beans to brew four 30ml short espressos into warmed demitasse cups. Serve 15ml anisette or sambuca beside each cup for pouring in. Cut four small curls from the remaining peel of the lemon used for the olives, avoiding bitter white pith, and serve one with each coffee.","shop":["36g espresso beans@Pantry","60ml anisette or sambuca@Bottle shop","1 lemon shared with snacks@Produce"]}],"shopping":["150g salted peanuts@Pantry","1/4 tsp chilli flakes@Pantry","120g sharp provolone@Deli","150g marinated olives@Deli","1 lemon@Produce","400g pizza dough@Bakery","50g butter@Dairy","5 garlic cloves@Produce","2 tbsp parsley@Produce","30g parmesan@Dairy","400g pork and beef mince@Meat","400g pork ribs@Meat","1 egg@Dairy","40g breadcrumbs@Pantry","salt@Pantry","black pepper@Pantry","2 tbsp olive oil@Pantry","1 onion@Produce","800g tinned tomatoes@Pantry","10 basil leaves@Produce","400g rigatoni@Pantry","250g fresh ricotta@Dairy","40g icing sugar@Pantry","1/2 tsp vanilla extract@Pantry","30g mini chocolate chips@Pantry","8 small cannoli shells@Bakery","30g pistachios@Pantry","36g espresso beans@Pantry","60ml anisette or sambuca@Bottle shop"]}}});
