Object.assign(MOVIE_MENU_EDITIONS,{"Inside Man (2006)":{"poster":"assets/menu-posters/inside-man-2006.jpg","colour":"#82652d","servings":4,"tagline":"The perfect heist needs a perfect lunch.","cue":"Serve the pizza when the hostages get their delivery.","menu":{"s":[{"n":"Hostage pizza bites","note":"Mini pizzas with tomato, mozzarella and pepperoni.","how":"Roll 500g pizza dough thin and cut 16 rounds with a glass. Top each with a spoon of pizza sauce, using 150ml, a pinch of grated mozzarella, 150g in total, and a slice of pepperoni. Bake at 230C for 8 minutes until golden underneath.","shop":["500g pizza dough@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy","16 slices pepperoni@Deli"]},{"n":"Brooklyn potato knishes","note":"Potato and slow onion in puff pastry logs with hot mustard.","how":"Boil 500g peeled potatoes 15 minutes and mash. Cook 1 diced brown onion in 30g butter over low heat for 15 minutes and mix in with salt and white pepper. Spread along 2 sheets puff pastry, roll into logs, cut into 8 and brush with 1 beaten egg. Bake at 200C for 25 minutes. Serve with 40g hot English mustard.","shop":["500g potatoes@Produce","1 brown onion@Produce","30g butter@Dairy","2 sheets puff pastry@Frozen","1 egg@Dairy","40g hot English mustard@Pantry"]}],"m":[{"n":"Manhattan steak sandwich","note":"Sliced sirloin on ciabatta with slow onions, rocket and horseradish cream.","how":"Cook 2 sliced brown onions in butter over low heat for 30 minutes until jammy. Sear 2 sirloin steaks, about 600g, hard for 3 minutes a side, rest and slice thin. Split and toast 4 pieces of ciabatta, spread with 100g horseradish cream and pile with steak, onions and 60g rocket.","shop":["2 brown onions@Produce","20g butter@Dairy","600g sirloin steak@Meat","4 ciabatta rolls@Bakery","100g horseradish cream@Pantry","60g rocket@Produce"]}],"w":[{"n":"Black and white cookies","note":"Soft vanilla cookies iced half vanilla, half chocolate.","how":"Beat 115g butter with 150g caster sugar, add 1 egg, 80g sour cream and 1 tsp vanilla, then mix in 250g plain flour and 1 tsp baking powder. Scoop 12 mounds and bake at 180C for 12 minutes. Ice half of each flat side with 250g icing sugar mixed with hot water, then stir 2 tbsp cocoa into the rest for the other half.","shop":["115g butter@Dairy","150g caster sugar@Pantry","1 egg@Dairy","80g sour cream@Dairy","1 tsp vanilla extract@Pantry","250g plain flour@Pantry","1 tsp baking powder@Pantry","250g icing sugar@Pantry","2 tbsp cocoa@Pantry"]}],"d":[{"n":"Espresso","note":"Short double ristretto with a glass of water.","how":"For each cup, grind 18g espresso beans fine and pull a short double, about 25g in the cup. Make four, using 72g beans, and serve each with a small glass of water.","shop":["72g espresso beans@Pantry"]}],"shopping":["500g pizza dough@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy","16 slices pepperoni@Deli","500g potatoes@Produce","1 brown onion@Produce","165g butter@Dairy","2 sheets puff pastry@Frozen","2 egg@Dairy","40g hot English mustard@Pantry","2 brown onions@Produce","600g sirloin steak@Meat","4 ciabatta rolls@Bakery","100g horseradish cream@Pantry","60g rocket@Produce","150g caster sugar@Pantry","80g sour cream@Dairy","1 tsp vanilla extract@Pantry","250g plain flour@Pantry","1 tsp baking powder@Pantry","250g icing sugar@Pantry","2 tbsp cocoa@Pantry","72g espresso beans@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Escape from New York (1981)":{"poster":"assets/menu-posters/escape-from-new-york-1981.jpg","colour":"#b93423","servings":4,"tagline":"Get in. Get the President. Get dinner.","cue":"Serve the mains when the Duke rolls up in his chandelier car.","menu":{"s":[{"n":"Cabbie's road snacks","note":"Beef jerky and honey-roasted peanuts with a few dried chillies.","how":"Tip 150g beef jerky and 200g honey-roasted peanuts into a big paper bag. Add 4 dried chillies broken in half for a bit of heat, close the top and shake well. Serve straight from the bag.","shop":["150g beef jerky@Pantry","200g honey-roasted peanuts@Pantry","4 dried chillies@Pantry"]},{"n":"Survival tin sardines","note":"Sardines on saltine crackers with lemon, hot sauce and parsley.","how":"Drain 2 tins sardines in oil, about 220g. Lay a sardine on each of 24 saltine crackers, squeeze over lemon, add a drop of hot sauce and a little chopped parsley. Serve on the tin lids for the full survival look.","shop":["220g tinned sardines@Pantry","24 saltine crackers@Pantry","1 lemon@Produce","1 tsp hot sauce@Pantry","1 bunch parsley@Produce"]}],"m":[{"n":"Liberty Island burgers","note":"Double smashed patties with cheese, grilled onion, pickles and mustard.","how":"Roll 800g beef mince into 8 balls. Smash each flat on a smoking flat-top or heavy pan, season, cook 2 minutes, flip and add a slice of American cheese. Grill 1 sliced brown onion alongside. Stack two patties per toasted bun with the onion, sliced pickles and yellow mustard.","shop":["800g beef mince@Meat","8 slices American cheese@Dairy","1 brown onion@Produce","4 burger buns@Bakery","4 dill pickles@Pantry","3 tbsp yellow mustard@Pantry"]}],"w":[{"n":"Ration bars","note":"Chewy golden syrup oat bars topped with dark chocolate.","how":"Melt 150g butter with 3 tbsp golden syrup and 100g brown sugar, then stir in 250g rolled oats. Press into a lined 20cm square tin and bake at 180C for 20 minutes. Cool, spread with 100g melted dark chocolate and cut into 12 bars once set.","shop":["150g butter@Dairy","3 tbsp golden syrup@Pantry","100g brown sugar@Pantry","250g rolled oats@Pantry","100g dark chocolate@Pantry"]}],"d":[{"n":"Black coffee","note":"Drip coffee served black in steel mugs.","how":"Brew 1 litre of drip coffee with 60g ground coffee. Pour black into four steel mugs and keep the pot hot on the stove for refills through the night.","shop":["60g ground coffee@Pantry"]}],"shopping":["150g beef jerky@Pantry","200g honey-roasted peanuts@Pantry","4 dried chillies@Pantry","220g tinned sardines@Pantry","24 saltine crackers@Pantry","1 lemon@Produce","1 tsp hot sauce@Pantry","1 bunch parsley@Produce","800g beef mince@Meat","8 slices American cheese@Dairy","1 brown onion@Produce","4 burger buns@Bakery","4 dill pickles@Pantry","3 tbsp yellow mustard@Pantry","150g butter@Dairy","3 tbsp golden syrup@Pantry","100g brown sugar@Pantry","250g rolled oats@Pantry","100g dark chocolate@Pantry","60g ground coffee@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Serpico (1973)":{"poster":"assets/menu-posters/serpico-1973.jpg","colour":"#656235","servings":4,"tagline":"One honest cop. No free sandwiches.","cue":"Serve the mains when Frank turns down the free meal at the deli.","menu":{"s":[{"n":"Village bagels and lox","note":"Toasted bagels with cream cheese, lox, capers, onion and dill.","how":"Split and toast 4 bagels. Spread each half thickly with cream cheese, using 200g in total. Top with 200g smoked salmon, 1 tbsp capers, thinly sliced red onion and small sprigs of dill. Cut each half in two to share.","shop":["4 bagels@Bakery","200g cream cheese@Dairy","200g smoked salmon@Seafood","1 tbsp capers@Pantry","1 red onion@Produce","1 bunch dill@Produce"]},{"n":"Hot pretzels","note":"Bakery soft pretzels refreshed with butter and salt, mustard alongside.","how":"Brush 4 soft pretzels with 20g melted butter and sprinkle with 1 tsp rock salt. Bake at 200C for 5 minutes until hot and glossy. Cut in half and serve with 100g yellow mustard.","shop":["4 soft pretzels@Bakery","20g butter@Dairy","1 tsp rock salt@Pantry","100g yellow mustard@Pantry"]}],"m":[{"n":"Deli hero, paid for","note":"Steamed pastrami heroes with Swiss, coleslaw and Russian dressing.","how":"Steam 500g sliced pastrami for 10 minutes until glossy. Mix 100g mayonnaise with 2 tbsp tomato sauce, 1 tsp horseradish and 1 tbsp chopped pickle for Russian dressing. Toss 250g coleslaw mix with half the dressing. Fill 4 long rolls with pastrami, 8 slices Swiss cheese, the slaw and the rest of the dressing.","shop":["500g pastrami@Deli","100g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tsp horseradish@Pantry","1 dill pickle@Pantry","250g coleslaw mix@Produce","4 long rolls@Bakery","8 slices Swiss cheese@Deli"]}],"w":[{"n":"Black and white cookies","note":"Soft vanilla cookies iced half vanilla, half chocolate.","how":"Beat 115g butter with 150g caster sugar, add 1 egg, 80g sour cream and 1 tsp vanilla, then mix in 250g plain flour and 1 tsp baking powder. Scoop 12 mounds onto lined trays and bake at 180C for 12 minutes. Make a thick icing with 250g icing sugar and hot water, ice half of each flat side, then add 2 tbsp cocoa to the rest and ice the other half.","shop":["115g butter@Dairy","150g caster sugar@Pantry","1 egg@Dairy","80g sour cream@Dairy","1 tsp vanilla extract@Pantry","250g plain flour@Pantry","1 tsp baking powder@Pantry","250g icing sugar@Pantry","2 tbsp cocoa@Pantry"]}],"d":[{"n":"Diner coffee, paid for","note":"Drip coffee in thick mugs, paid for before you drink it.","how":"Brew 1 litre of drip coffee with 60g ground coffee. Pour into four thick mugs with 200ml milk on the side. Pay for it first, the way Serpico always did.","shop":["60g ground coffee@Pantry","200ml full cream milk@Dairy"]}],"shopping":["4 bagels@Bakery","200g cream cheese@Dairy","200g smoked salmon@Seafood","1 tbsp capers@Pantry","1 red onion@Produce","1 bunch dill@Produce","4 soft pretzels@Bakery","135g butter@Dairy","1 tsp rock salt@Pantry","100g yellow mustard@Pantry","500g pastrami@Deli","100g mayonnaise@Pantry","2 tbsp tomato sauce@Pantry","1 tsp horseradish@Pantry","1 dill pickle@Pantry","250g coleslaw mix@Produce","4 long rolls@Bakery","8 slices Swiss cheese@Deli","150g caster sugar@Pantry","1 egg@Dairy","80g sour cream@Dairy","1 tsp vanilla extract@Pantry","250g plain flour@Pantry","1 tsp baking powder@Pantry","250g icing sugar@Pantry","2 tbsp cocoa@Pantry","60g ground coffee@Pantry","200ml full cream milk@Dairy"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Home Alone 2: Lost in New York (1992)":{"poster":"assets/menu-posters/home-alone-2-lost-in-new-york-1992.jpg","colour":"#205139","servings":4,"tagline":"Room service. Charge it to Dad.","cue":"Order room service when Kevin gets his own suite.","menu":{"s":[{"n":"Plaza minibar mix","note":"Buttery rosemary nuts with chocolate almonds and pretzels.","how":"Melt 30g butter with 2 tbsp brown sugar and 1 tbsp chopped rosemary. Toss through 300g mixed nuts, spread on a tray and roast at 170C for 12 minutes, stirring once. Cool, then mix with 150g chocolate almonds and 100g pretzels.","shop":["30g butter@Dairy","2 tbsp brown sugar@Pantry","1 bunch rosemary@Produce","300g mixed nuts@Pantry","150g chocolate almonds@Pantry","100g pretzels@Pantry"]},{"n":"Limo pizza bites","note":"Toasted English muffins with pizza sauce and bubbling mozzarella.","how":"Split 4 English muffins and toast lightly. Spread each half with pizza sauce, using 150ml in total, and top with 150g grated mozzarella. Grill for 3 to 4 minutes until bubbling and spotted brown. Cut into halves to serve.","shop":["4 English muffins@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy"]}],"m":[{"n":"Lobster mac and cheese","note":"Macaroni in Gruyère cheese sauce with butter-poached lobster and crumbs.","how":"Gently poach the meat of 2 lobster tails in 40g butter for 4 minutes and chop. Melt 40g butter, stir in 40g flour, then whisk in 600ml warm milk and simmer 5 minutes. Stir in 120g grated Gruyère and 100g cheddar. Fold through 400g cooked macaroni and the lobster, tip into a dish, top with 40g panko mixed with 20g melted butter and bake at 200C for 20 minutes.","shop":["2 lobster tails@Seafood","100g butter@Dairy","40g plain flour@Pantry","600ml full cream milk@Dairy","120g Gruyère@Deli","100g cheddar@Dairy","400g macaroni@Pantry","40g panko@Pantry"]}],"w":[{"n":"Room service sundae","note":"Towering sundae with hot fudge, cream, nuts, sprinkles and a cherry.","how":"Melt 100g dark chocolate with 100ml thickened cream for hot fudge. Whip another 200ml cream. Pile 8 scoops vanilla ice cream into four tall glasses, pour over the fudge, add the cream, 40g chopped nuts, sprinkles and a maraschino cherry on each.","shop":["100g dark chocolate@Pantry","300ml thickened cream@Dairy","1L vanilla ice cream@Frozen","40g mixed nuts@Pantry","1 jar sprinkles@Pantry","4 maraschino cherries@Pantry"]}],"d":[{"n":"Hot chocolate with whipped cream","note":"Rich hot chocolate topped with whipped cream and marshmallows.","how":"Heat 1 litre full cream milk until steaming and whisk in 150g chopped dark chocolate until smooth. Pour into four mugs, top with 150ml whipped thickened cream and a handful of marshmallows.","shop":["1L full cream milk@Dairy","150g dark chocolate@Pantry","150ml thickened cream@Dairy","100g marshmallows@Pantry"]}],"shopping":["130g butter@Dairy","2 tbsp brown sugar@Pantry","1 bunch rosemary@Produce","340g mixed nuts@Pantry","150g chocolate almonds@Pantry","100g pretzels@Pantry","4 English muffins@Bakery","150ml pizza sauce@Pantry","150g mozzarella@Dairy","2 lobster tails@Seafood","40g plain flour@Pantry","1.6L full cream milk@Dairy","120g Gruyère@Deli","100g cheddar@Dairy","400g macaroni@Pantry","40g panko@Pantry","250g dark chocolate@Pantry","450ml thickened cream@Dairy","1L vanilla ice cream@Frozen","1 jar sprinkles@Pantry","4 maraschino cherries@Pantry","100g marshmallows@Pantry"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Departed (2006)":{"poster":"assets/menu-posters/the-departed-2006.jpg","colour":"#233c52","servings":4,"tagline":"Two rats. One city. Plenty of chowder.","cue":"Serve the mains when Costigan and Sullivan figure out who the other one is.","menu":{"s":[{"n":"Boston clam chowder cups","note":"Creamy clam and potato chowder with bacon and oyster crackers.","how":"Fry 150g diced bacon until crisp, then sweat 1 diced onion and 2 celery sticks in the fat. Add 400g diced potatoes, 500ml clam juice or fish stock and thyme and simmer 15 minutes. Stir in 250g chopped clam meat and 200ml cream for the last 3 minutes. Serve in cups with 100g oyster crackers.","shop":["150g bacon@Meat","1 brown onion@Produce","2 celery sticks@Produce","400g potatoes@Produce","500ml fish stock@Pantry","250g clam meat@Seafood","200ml thickened cream@Dairy","100g oyster crackers@Pantry"]},{"n":"Southie bar fries","note":"Double-fried chips with malt vinegar and salt in paper cones.","how":"Cut 1kg potatoes into chips, rinse and dry. Fry at 140C for 6 minutes until soft, rest 20 minutes, then fry at 185C until crisp. Salt well, splash with 3 tbsp malt vinegar and serve in paper cones.","shop":["1kg potatoes@Produce","1.5L vegetable oil@Pantry","3 tbsp malt vinegar@Pantry"]}],"m":[{"n":"Southie fish and chips","note":"Lager-battered flathead with chips, minted mushy peas and malt vinegar.","how":"Whisk 200g plain flour, 50g cornflour and 330ml ice-cold lager into a batter. Dust 800g flathead fillets in flour, dip and fry at 180C for 4 minutes. Fry 1kg potatoes as chips at 140C then 185C. Cook 400g frozen peas, crush with butter and mint. Serve with malt vinegar.","shop":["200g plain flour@Pantry","50g cornflour@Pantry","330ml lager@Bottle shop","800g flathead fillets@Seafood","1kg potatoes@Produce","400g frozen peas@Frozen","20g butter@Dairy","1 bunch mint@Produce","2L vegetable oil@Pantry","2 tbsp malt vinegar@Pantry"]}],"w":[{"n":"Boston cream pie","note":"Two sponge layers filled with vanilla custard under dark chocolate ganache.","how":"Whisk 4 eggs and 120g sugar until thick, fold in 120g flour and bake in two 20cm tins at 180C for 18 minutes. For custard, heat 300ml milk, whisk into 3 yolks, 60g sugar and 25g cornflour and cook until thick, then cool. Sandwich the sponges with custard. Melt 100g dark chocolate with 100ml cream and pour over the top.","shop":["7 eggs@Dairy","180g caster sugar@Pantry","120g plain flour@Pantry","300ml full cream milk@Dairy","25g cornflour@Pantry","100g dark chocolate@Pantry","100ml thickened cream@Dairy"]}],"d":[{"n":"Cranberry juice","note":"Cranberry juice over ice, with vodka if you need to keep your cover.","how":"Fill four short glasses with ice and pour 150ml cranberry juice into each. For anyone keeping their cover, add 30ml vodka, about 120ml for four.","shop":["600ml cranberry juice@Drinks","120ml vodka@Bottle shop","1kg ice@Frozen"]}],"shopping":["150g bacon@Meat","1 brown onion@Produce","2 celery sticks@Produce","2.4kg potatoes@Produce","500ml fish stock@Pantry","250g clam meat@Seafood","300ml thickened cream@Dairy","100g oyster crackers@Pantry","3.5L vegetable oil@Pantry","5 tbsp malt vinegar@Pantry","320g plain flour@Pantry","75g cornflour@Pantry","330ml lager@Bottle shop","800g flathead fillets@Seafood","400g frozen peas@Frozen","20g butter@Dairy","1 bunch mint@Produce","7 eggs@Dairy","180g caster sugar@Pantry","300ml full cream milk@Dairy","100g dark chocolate@Pantry","600ml cranberry juice@Drinks","120ml vodka@Bottle shop","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Get Shorty (1995)":{"poster":"assets/menu-posters/get-shorty-1995.jpg","colour":"#e15f20","servings":4,"tagline":"Look at me. Now pass the dip.","cue":"Serve the mains when Chili starts pitching his movie idea.","menu":{"s":[{"n":"Miami prawn cocktail","note":"Iced prawns on sliced avocado with a lime and horseradish cocktail sauce.","how":"Poach 500g peeled green prawns for 2 minutes in salted water, then chill in iced water. Mix 120ml tomato sauce with the juice of 1 lime, 1 tsp horseradish and a pinch of chilli flakes. Fan 2 sliced avocados across four plates, pile on the prawns and spoon over the sauce. Serve with lime wedges.","shop":["500g green prawns@Seafood","2 limes@Produce","2 avocados@Produce","120ml tomato sauce@Pantry","1 tsp horseradish@Pantry"]},{"n":"Diner fries","note":"Hand-cut chips fried twice until crisp and salted straight away.","how":"Cut 1kg potatoes into chips and rinse well. Fry at 140C for 6 minutes until soft but pale, drain and rest 20 minutes. Fry again at 185C for 3 to 4 minutes until crisp and golden. Salt straight away with fine salt and serve in paper cones.","shop":["1kg potatoes@Produce","1.5L vegetable oil@Pantry","1 tsp fine salt@Pantry"]}],"m":[{"n":"Chili Palmer's steak frites","note":"Seared sirloin with red wine butter sauce and double-fried frites.","how":"Fry 1kg potatoes cut into thin frites at 140C for 5 minutes, rest, then at 185C until crisp. Season 4 sirloin steaks, about 800g, sear hard for 3 minutes a side and rest. Sweat 2 chopped shallots in the pan fat, add 150ml red wine and reduce by two thirds, then whisk in 50g cold butter. Slice the steak and spoon the sauce over.","shop":["1kg potatoes@Produce","1.5L vegetable oil@Pantry","800g sirloin steak@Meat","2 shallots@Produce","150ml red wine@Bottle shop","50g butter@Dairy"]}],"w":[{"n":"B-movie popcorn sundae","note":"Vanilla ice cream with hot fudge, caramel popcorn and salted peanuts.","how":"Pop 40g popcorn kernels. Melt 50g butter with 80g brown sugar, toss through the popcorn and bake at 150C for 10 minutes to set. Melt 100g dark chocolate with 100ml cream for hot fudge. Scoop 8 balls of vanilla ice cream into four bowls, pour over the fudge and top with the popcorn and 50g salted peanuts.","shop":["40g popcorn kernels@Pantry","50g butter@Dairy","80g brown sugar@Pantry","100g dark chocolate@Pantry","100ml thickened cream@Dairy","1L vanilla ice cream@Frozen","50g salted peanuts@Pantry"]}],"d":[{"n":"Bloody Mary","note":"Spiced vodka and tomato juice rolled between tins, with a celery stick.","how":"For each drink, put 45ml vodka, 120ml tomato juice, 10ml lemon juice, 2 dashes Worcestershire sauce, 2 dashes hot sauce and a pinch each of celery salt and pepper in a tin with ice. Pour back and forth between two tins 5 times, strain over fresh ice and add a celery stick. Makes four.","shop":["180ml vodka@Bottle shop","500ml tomato juice@Drinks","1 lemon@Produce","1 tsp Worcestershire sauce@Pantry","1 tsp hot sauce@Pantry","4 celery sticks@Produce","1kg ice@Frozen"]}],"shopping":["500g green prawns@Seafood","2 limes@Produce","2 avocados@Produce","120ml tomato sauce@Pantry","1 tsp horseradish@Pantry","2kg potatoes@Produce","3L vegetable oil@Pantry","1 tsp fine salt@Pantry","800g sirloin steak@Meat","2 shallots@Produce","150ml red wine@Bottle shop","100g butter@Dairy","40g popcorn kernels@Pantry","80g brown sugar@Pantry","100g dark chocolate@Pantry","100ml thickened cream@Dairy","1L vanilla ice cream@Frozen","50g salted peanuts@Pantry","180ml vodka@Bottle shop","500ml tomato juice@Drinks","1 lemon@Produce","1 tsp Worcestershire sauce@Pantry","1 tsp hot sauce@Pantry","4 celery sticks@Produce","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Bugsy (1991)":{"poster":"assets/menu-posters/bugsy-1991.jpg","colour":"#b78a37","servings":4,"tagline":"He dreamed up Las Vegas. Then he blew the budget.","cue":"Serve dessert when the Flamingo finally opens its doors.","menu":{"s":[{"n":"Hollywood party blini and caviar","note":"Warm blini with crème fraîche, salmon roe and chives.","how":"Warm 16 buckwheat blini at 180C for 5 minutes. Top each with a teaspoon of crème fraîche, half a teaspoon of salmon roe and snipped chives. Serve straight away on a silver tray.","shop":["16 buckwheat blini@Bakery","100g crème fraîche@Dairy","50g salmon roe@Seafood","1 bunch chives@Produce"]},{"n":"Desert devilled eggs","note":"Devilled eggs whipped with mayo, mustard and cayenne.","how":"Boil 8 eggs for 10 minutes, cool in iced water and peel. Halve and whip the yolks with 3 tbsp mayonnaise, 1 tsp Dijon mustard, a pinch of cayenne and 1 tsp pickle juice until smooth. Pipe back into the whites and dust with smoked paprika.","shop":["8 eggs@Dairy","3 tbsp mayonnaise@Pantry","1 jar Dijon mustard@Pantry","1 pinch cayenne pepper@Pantry","1 tsp smoked paprika@Pantry"]}],"m":[{"n":"Flamingo steak Diane","note":"Seared scotch fillet in a brandy, mustard and cream pan sauce.","how":"Flatten 4 scotch fillet steaks, about 800g, and sear hot for 2 minutes a side, then rest. In the same pan, soften 2 chopped shallots and 1 garlic clove in 30g butter, add 60ml brandy and flame. Stir in 1 tbsp Dijon mustard, 1 tbsp Worcestershire sauce, 150ml beef stock and 150ml cream and reduce 4 minutes. Return the steaks to coat.","shop":["800g scotch fillet@Meat","2 shallots@Produce","1 garlic clove@Produce","30g butter@Dairy","60ml brandy@Bottle shop","1 jar Dijon mustard@Pantry","1 tbsp Worcestershire sauce@Pantry","150ml beef stock@Pantry","150ml thickened cream@Dairy"]}],"w":[{"n":"Pink flamingo pavlova","note":"Crisp pavlova with pink raspberry cream.","how":"Whisk 4 egg whites to soft peaks, then add 220g caster sugar a spoon at a time until glossy. Fold in 1 tsp cornflour and 1 tsp white vinegar, spread into a round and bake at 120C for 90 minutes, then cool in the oven. Whip 300ml thickened cream and fold through 125g crushed raspberries. Pile on top just before serving.","shop":["4 eggs@Dairy","220g caster sugar@Pantry","1 tsp cornflour@Pantry","1 tsp white vinegar@Pantry","300ml thickened cream@Dairy","125g raspberries@Produce"]}],"d":[{"n":"Champagne","note":"Brut champagne chilled hard and poured into coupes.","how":"Chill one 750ml bottle of brut champagne to about 7C, around 3 hours in the fridge or 30 minutes in an ice bucket. Pour into four coupes, about 180ml each.","shop":["750ml champagne@Bottle shop"]}],"shopping":["16 buckwheat blini@Bakery","100g crème fraîche@Dairy","50g salmon roe@Seafood","1 bunch chives@Produce","12 eggs@Dairy","3 tbsp mayonnaise@Pantry","2 jar Dijon mustard@Pantry","1 pinch cayenne pepper@Pantry","1 tsp smoked paprika@Pantry","800g scotch fillet@Meat","2 shallots@Produce","1 garlic clove@Produce","30g butter@Dairy","60ml brandy@Bottle shop","1 tbsp Worcestershire sauce@Pantry","150ml beef stock@Pantry","450ml thickened cream@Dairy","220g caster sugar@Pantry","1 tsp cornflour@Pantry","1 tsp white vinegar@Pantry","125g raspberries@Produce","750ml champagne@Bottle shop"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Donnie Brasco (1997)":{"poster":"assets/menu-posters/donnie-brasco-1997.jpg","colour":"#24413d","servings":4,"tagline":"Forget about it.","cue":"Before the mains, explain all the meanings of \"forget about it\" to the table.","menu":{"s":[{"n":"Miami garlic prawns","note":"Butterflied prawns sizzled with garlic, chilli, white wine and butter.","how":"Butterfly 500g green prawns. Heat 3 tbsp olive oil until very hot, add the prawns with 4 sliced garlic cloves and a pinch of chilli flakes and cook 2 minutes. Add 80ml white wine, bubble for a minute, then swirl in 30g butter and chopped parsley. Serve in the pan with crusty bread for the juices.","shop":["500g green prawns@Seafood","3 tbsp olive oil@Pantry","4 garlic cloves@Produce","80ml white wine@Bottle shop","30g butter@Dairy","1 bunch parsley@Produce","1 baguette@Bakery"]},{"n":"Fried mozzarella","note":"Golden crumbed mozzarella fingers with warm tomato sauce to dip.","how":"Cut 400g low-moisture mozzarella into 16 fingers and freeze 20 minutes. Dip in 50g flour, then 2 beaten eggs, then 100g breadcrumbs, then egg and crumbs again. Fry at 180C for 90 seconds until golden. Warm 250ml passata with a pinch of salt and oregano for dipping.","shop":["400g low-moisture mozzarella@Dairy","50g plain flour@Pantry","2 eggs@Dairy","100g breadcrumbs@Pantry","250ml passata@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Shoes-on teriyaki steak","note":"Seared sirloin brushed with sticky teriyaki, with rice and greens.","how":"Simmer 80ml soy sauce, 80ml mirin, 60ml sake and 2 tbsp sugar for 5 minutes until syrupy. Sear 4 sirloin steaks, about 800g, in a smoking pan for 3 minutes a side, brushing with glaze in the last minute. Rest 5 minutes and slice. Serve with 400g steamed short grain rice and 4 blanched bok choy.","shop":["80ml soy sauce@Pantry","80ml mirin@Pantry","60ml sake@Bottle shop","2 tbsp caster sugar@Pantry","800g sirloin steak@Meat","400g short grain rice@Pantry","4 bok choy@Produce"]}],"w":[{"n":"Ricotta cheesecake","note":"Light baked ricotta cheesecake with lemon and vanilla.","how":"Drain 750g fresh ricotta in a sieve for 2 hours. Beat with 150g caster sugar, 4 eggs, the zest of 1 lemon and 1 tsp vanilla extract until smooth. Pour into a lined 22cm springform tin and bake at 160C for 60 minutes. Turn off the oven and cool inside with the door ajar. Dust with icing sugar to serve.","shop":["750g fresh ricotta@Dairy","150g caster sugar@Pantry","4 eggs@Dairy","1 lemon@Produce","1 tsp vanilla extract@Pantry","1 tbsp icing sugar@Pantry"]}],"d":[{"n":"Scotch on the rocks","note":"Blended Scotch over one big ice cube in a heavy tumbler.","how":"Put a single large ice cube in each of four heavy tumblers. Pour 45ml blended Scotch over each, about 180ml in total. Serve straight away, no garnish.","shop":["180ml blended Scotch@Bottle shop","4 large ice cubes@Frozen"]}],"shopping":["500g green prawns@Seafood","3 tbsp olive oil@Pantry","4 garlic cloves@Produce","80ml white wine@Bottle shop","30g butter@Dairy","1 bunch parsley@Produce","1 baguette@Bakery","400g low-moisture mozzarella@Dairy","50g plain flour@Pantry","6 eggs@Dairy","100g breadcrumbs@Pantry","250ml passata@Pantry","1L vegetable oil@Pantry","80ml soy sauce@Pantry","80ml mirin@Pantry","60ml sake@Bottle shop","800g sirloin steak@Meat","400g short grain rice@Pantry","4 bok choy@Produce","750g fresh ricotta@Dairy","180g caster sugar@Pantry","1 lemon@Produce","1 tsp vanilla extract@Pantry","1 tbsp icing sugar@Pantry","180ml blended Scotch@Bottle shop","4 large ice cubes@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"Carlito's Way (1993)":{"poster":"assets/menu-posters/carlitos-way-1993.jpg","colour":"#9f2442","servings":4,"tagline":"One last score, then paradise.","cue":"Have dessert on the table before the Grand Central finale.","menu":{"s":[{"n":"Bacalaitos","note":"Lacy salt cod fritters with garlic and coriander.","how":"Soak 250g salt cod for 24 hours, changing the water three times, then flake. Whisk 200g plain flour, 2 tsp baking powder, 300ml water, 2 crushed garlic cloves and a handful of chopped coriander into a loose batter and fold in the cod. Fry wide flat spoonfuls in 180C oil until golden and lacy, drain and salt.","shop":["250g salt cod@Seafood","200g plain flour@Pantry","2 tsp baking powder@Pantry","2 garlic cloves@Produce","1 bunch coriander@Produce","1L vegetable oil@Pantry"]},{"n":"Tostones","note":"Twice-fried smashed green plantain with garlic and lime mojo.","how":"Peel 3 green plantains and cut into 3cm chunks. Fry at 160C for 4 minutes until soft, smash flat with a heavy glass and fry again at 190C until crisp. Salt well. Mix 3 crushed garlic cloves with the juice of 2 limes and 60ml olive oil and spoon over.","shop":["3 green plantains@Produce","3 garlic cloves@Produce","2 limes@Produce","60ml extra virgin olive oil@Pantry","1L vegetable oil@Pantry"]}],"m":[{"n":"Pernil","note":"Garlic and oregano roast pork shoulder with crackling, rice and pigeon peas.","how":"Stab a 2kg pork shoulder all over and rub with 8 crushed garlic cloves, 2 tsp dried oregano, 2 tsp salt and 2 tbsp white vinegar. Marinate overnight. Roast skin up at 160C for 5 hours, then 230C for 20 minutes to crackle. Cook 400g long grain rice with a 400g tin of pigeon peas, stock and a little onion to serve alongside.","shop":["2kg pork shoulder@Meat","8 garlic cloves@Produce","2 tsp dried oregano@Pantry","2 tbsp white vinegar@Pantry","400g long grain rice@Pantry","400g pigeon peas@Pantry"]}],"w":[{"n":"Paradise flan","note":"Coconut caramel flan, baked slowly and turned out cold.","how":"Melt 150g caster sugar in a pan until deep amber and pour into a ring tin. Blend a 395g tin condensed milk, 270ml coconut milk, 375ml evaporated milk and 5 eggs and pour over the caramel. Bake in a water bath at 160C for 50 minutes until just set. Chill overnight, run a knife around and turn out onto a plate.","shop":["150g caster sugar@Pantry","395g condensed milk@Pantry","270ml coconut milk@Pantry","375ml evaporated milk@Pantry","5 eggs@Dairy"]}],"d":[{"n":"Rum and cola","note":"Golden rum over ice with cold cola and a big squeeze of lime.","how":"Fill four tall glasses with ice. Pour 45ml golden rum into each, about 180ml in total, top with cold cola and squeeze in a big wedge of lime, about 2 limes for four drinks.","shop":["180ml golden rum@Bottle shop","1.25L cola@Drinks","2 limes@Produce","1kg ice@Frozen"]}],"shopping":["250g salt cod@Seafood","200g plain flour@Pantry","2 tsp baking powder@Pantry","13 garlic cloves@Produce","1 bunch coriander@Produce","2L vegetable oil@Pantry","3 green plantains@Produce","4 limes@Produce","60ml extra virgin olive oil@Pantry","2kg pork shoulder@Meat","2 tsp dried oregano@Pantry","2 tbsp white vinegar@Pantry","400g long grain rice@Pantry","400g pigeon peas@Pantry","150g caster sugar@Pantry","395g condensed milk@Pantry","270ml coconut milk@Pantry","375ml evaporated milk@Pantry","5 eggs@Dairy","180ml golden rum@Bottle shop","1.25L cola@Drinks","1kg ice@Frozen"]}}});
Object.assign(MOVIE_MENU_EDITIONS,{"The Godfather Part III (1990)":{"poster":"assets/menu-posters/the-godfather-part-iii-1990.jpg","colour":"#711e19","servings":4,"tagline":"The past never stays buried.","cue":"Hold the cannoli until the opera in the final act, and keep an eye on who made them.","menu":{"s":[{"n":"Palermo panelle","note":"Golden chickpea fritters fried crisp, finished with lemon and salt.","how":"Whisk 250g chickpea flour into 750ml cold water with 1 tsp salt until smooth. Cook over medium heat, stirring constantly, for 10 minutes until very thick. Add 2 tbsp chopped parsley, spread 1cm thick on an oiled tray and leave to set for 1 hour. Cut into squares and fry in 180C oil until puffed and golden. Drain, salt, and serve with lemon wedges.","shop":["250g chickpea flour@Pantry","1 bunch parsley@Produce","2 lemons@Produce","1L vegetable oil@Pantry"]},{"n":"Prosciutto and melon","note":"Ripe rockmelon wedges draped with prosciutto, pepper and olive oil.","how":"Leave 1 rockmelon at room temperature for an hour. Halve, scoop out the seeds, cut into 12 long wedges and cut off the skin. Drape each wedge with a slice of prosciutto (about 150g in total), add a crack of black pepper and a drizzle of extra virgin olive oil just before serving.","shop":["1 rockmelon@Produce","150g prosciutto@Deli","2 tbsp extra virgin olive oil@Pantry"]}],"m":[{"n":"Pasta alla Norma","note":"Rigatoni with fried eggplant, tomato and basil, under grated ricotta salata.","how":"Cut 2 eggplants into thick half moons and fry in batches in 120ml olive oil until deep gold, drain. Fry 3 sliced garlic cloves in 2 tbsp of the oil, add 800g San Marzano tomatoes and a handful of basil, simmer 20 minutes and season. Cook 500g rigatoni until al dente, toss with the sauce, eggplant and a splash of pasta water. Grate 100g ricotta salata heavily over the top.","shop":["2 eggplants@Produce","120ml olive oil@Pantry","3 garlic cloves@Produce","800g San Marzano tomatoes@Pantry","1 bunch basil@Produce","500g rigatoni@Pantry","100g ricotta salata@Deli"]}],"w":[{"n":"Opera night cannoli","note":"Crisp shells filled with sweet ricotta, candied orange and pistachio.","how":"Drain 500g fresh ricotta in a sieve for 2 hours. Beat with 80g icing sugar, 1/2 tsp ground cinnamon and 40g finely chopped candied orange peel. Spoon into a piping bag and fill 8 cannoli shells just before serving. Dip each end in 30g chopped pistachios and dust with a little more icing sugar.","shop":["500g fresh ricotta@Dairy","80g icing sugar@Pantry","1/2 tsp ground cinnamon@Pantry","40g candied orange peel@Pantry","8 cannoli shells@Bakery","30g pistachios@Pantry"]}],"d":[{"n":"Nero d'Avola","note":"Sicilian red opened early and served at cellar temperature.","how":"Open one 750ml bottle of Nero d'Avola 30 minutes before dinner and keep it at about 16C, cooler than the room. Pour into four large glasses, about 180ml each, with no ice.","shop":["750ml Nero d'Avola@Bottle shop"]}],"shopping":["250g chickpea flour@Pantry","1 bunch parsley@Produce","2 lemons@Produce","1L vegetable oil@Pantry","1 rockmelon@Produce","150g prosciutto@Deli","2 tbsp extra virgin olive oil@Pantry","2 eggplants@Produce","120ml olive oil@Pantry","3 garlic cloves@Produce","800g San Marzano tomatoes@Pantry","1 bunch basil@Produce","500g rigatoni@Pantry","100g ricotta salata@Deli","500g fresh ricotta@Dairy","80g icing sugar@Pantry","1/2 tsp ground cinnamon@Pantry","40g candied orange peel@Pantry","8 cannoli shells@Bakery","30g pistachios@Pantry","750ml Nero d'Avola@Bottle shop"]}}});
